DROP TABLE IF EXISTS person_rel;
CREATE TABLE person_rel (q TEXT, rq TEXT, rel TEXT);
CREATE INDEX i_prel ON person_rel(q);
DROP TABLE IF EXISTS person_timeline;
CREATE TABLE person_timeline (q TEXT, y INTEGER, y2 INTEGER, kind TEXT, label TEXT, ref INTEGER);
CREATE INDEX i_ptl ON person_timeline(q);
DROP TABLE IF EXISTS top100;
CREATE TABLE top100 (q TEXT PRIMARY KEY, grp TEXT, checked_at TEXT, photo INTEGER, intro INTEGER, timeline INTEGER, sns INTEGER, feed INTEGER, quotes INTEGER);
INSERT OR REPLACE INTO person VALUES ('100604534','Greg Brockman','グレッグ・ブロックマン','アメリカ合衆国の起業家、投資家、ソフトウェア開発者 (1987-)','グレッグ・ブロックマン（Greg Brockman）は、アメリカ合衆国の起業家、投資家、ソフトウェア開発者。OpenAIの社長。ストライプの元CTO、OpenAI共同創業者。','ja','グレッグ・ブロックマン');
INSERT OR REPLACE INTO person VALUES ('10126538','Taizo Son','孫泰蔵','日本の実業家 (1972-)','孫 泰藏（そん たいぞう、韓国名：손태장、1972年9月29日 - ）は、日本の実業家、投資家。','ja','孫泰蔵');
INSERT OR REPLACE INTO person VALUES ('102197117','Roberta Buffett Elliott','','American philanthropist','','','');
INSERT OR REPLACE INTO person VALUES ('102358882','Michael Rabbat','','Ph.D. University of Wisconsin-Madison 2006','','','');
INSERT OR REPLACE INTO person VALUES ('102411021','Andrew Konwinski','','Ph.D. University of California, Berkeley 2012','Andy Konwinski (born October 15, 1983) is an American computer scientist, businessman, and billionaire. He is known for co-founding Databricks, a data analytics and artificial intelligence (AI) platform, and for his early contributions to Apache Spark. He also co-founded Perplexity, an AI-powered search engine; the early-stage venture capital firm Laude Ventures; and Laude Institute, a nonprofit institute for computer science researchers.','en','Andy Konwinski');
INSERT OR REPLACE INTO person VALUES ('102649624','Jared Kaplan','ジャリッド・カプラン','artificial intelligence researcher','ジャリッド・ダニエル・カプラン（Jared Daniel Kaplan）は、アメリカ合衆国の理論物理学者・人工知能研究者であり、AIセーフティ企業Anthropicの共同創設者および最高科学責任者（CSO）を務める。また、ジョンズ・ホプキンス大学物理学・天文学科の准教授でもある（現在は休職中）。AIの性能がモデルの規模・データ量・計算量に従って冪乗則的に向上するという「スケーリング則（Scaling Laws）」の確立に中心的な役割を果たし、現代の大規模言語モデル開発の基礎を築いた。','ja','ジャリッド・カプラン');
INSERT OR REPLACE INTO person VALUES ('10314243','Kevin Systrom','ケビン・サイストロム','American computer programmer and entrepreneur (born 1983)','ケビン・シストロム（Kevin Systrom、1983年12月30日 - ）は、アメリカ合衆国のプログラマ、起業家。Instagram共同創業者で元CEO。','ja','ケビン・シストロム');
INSERT OR REPLACE INTO person VALUES ('10322797','MacKenzie Scott','マッケンジー・ベゾス','アメリカの資産家、小説家','マッケンジー・スコット（MacKenzie Scott、1970年4月7日生まれ）は、アメリカ人の小説家、フィランソロピスト（篤志家）。2014年にアマゾン創業者のジェフ・ベゾスが設立したいじめ対策プロジェクト、Bystander Revolutionのエグゼクティヴ・ディレクターも務める。 ジェフ・ベゾスは元夫であり、2019年に離婚。二人の間には養子も含め4人の子供がいる。 スコットは、ビル・ゲイツ、ウォーレン・バフェットが始動した「ギビング・プレッジ（寄付誓約宣言）」の署名者の一人として、自らの資産の半分以上を慈善活動に寄付することを公表している。2024年3月現在、スコットは1,600以上の慈善団体に総額172億ドルを寄付している。','ja','マッケンジー・スコット');
INSERT OR REPLACE INTO person VALUES ('103236782','John Schulman','ジョン・シュルマン','American computer scientist','John Schulman (born 1987 or 1988) is an American artificial intelligence researcher and co-founder of OpenAI. In August 2024, he announced he would be joining Anthropic. In February 2025, he announced he was leaving to join Thinking Machines Lab, where he is chief scientist.','en','John Schulman');
INSERT OR REPLACE INTO person VALUES ('10329947','Mike Krieger','マイク・クリーガー','Brazilian entrepreneur and software developer','マイケル・クリーガー（Michel Krieger、1986年3月4日 - ）は、アメリカ合衆国の起業家、ソフトウェアエンジニア。Instagram共同創業者で元CTO。現在は、Anthropicの最高製品責任者（CPO）。','ja','マイク・クリーガー');
INSERT OR REPLACE INTO person VALUES ('103335665','Dario Amodei','ダリオ・アモデイ','AnthropicのCEO兼共同創設者','ダリオ・アモデイ（Dario Amodei、1983年 - ）は、アメリカ合衆国の人工知能研究者であり、起業家。 大規模言語モデルのClaude AIを開発する企業Anthropicの共同創設者であり、CEOを務めている。OpenAIの元研究担当副社長であった。','ja','ダリオ・アモデイ');
INSERT OR REPLACE INTO person VALUES ('104721244','Elliot Rush Musk','エリオット・ラッシュ・ムスク','イーロン・マスクの異母弟','','','');
