INSERT OR REPLACE INTO person VALUES ('105100778','Nicole Shanahan','','American entrepreneur, attorney, and 2024 vice-presidential nominee of Robert F. Kennedy Jr. (born 1985)','Nicole Ann Shanahan (born September 26, 1985) is an American attorney and entrepreneur. She was the running mate of Robert F. Kennedy Jr. in his campaign in the 2024 U.S. presidential election. Born in California, Shanahan graduated from the University of Puget Sound and the Santa Clara University School of Law. Before law school, she worked as a paralegal and then as a patent specialist at the defensive patent aggregator RPX Corp.','en','Nicole Shanahan');
INSERT OR REPLACE INTO person VALUES ('105100797','Sam Brin','','Sergey Brin''s brother','','','');
