INSERT OR REPLACE INTO person VALUES ('105538968','Alexandra Musk','アレクサンドラ・マスク','half-sister of Elon Musk','','','');
INSERT OR REPLACE INTO person VALUES ('107434318','Sarah Friar','','American businesswoman, CEO of Nextdoor','Sarah Jane Friar (born 24 December 1972) is a British-Irish and American business executive, who has been the chief financial officer (CFO) of OpenAI since June 2024. She was the chief executive officer of American technology company Nextdoor from 2018 to 2024 and the CFO of Block, Inc. (formerly Square, Inc.) from 2012 to 2018.','en','Sarah Friar');
INSERT OR REPLACE INTO person VALUES ('108871755','Dylan Field','','American entrepreneur','Dylan Field (born 1992) is an American billionaire technology businessman, and co-founder of Figma, a web-based vector graphics editing software company. Field founded Figma in 2012 with Evan Wallace, whom he had met while they were computer science students at Brown University. In 2012, Field received a Thiel Fellowship, a $100,000 grant conditioned on his leaving school to begin working full-time on the company.','en','Dylan Field');
INSERT OR REPLACE INTO person VALUES ('110864219','Aidan Gomez','','artificial intelligence researcher','Aidan Gomez is a British-Canadian computer scientist working in the field of artificial intelligence, with a focus on natural language processing. He is the co-founder and CEO of the technology company Cohere.','en','Aidan Gomez');
INSERT OR REPLACE INTO person VALUES ('111363577','Asha Rose Musk','','half-sister of Elon Musk','','','');
INSERT OR REPLACE INTO person VALUES ('112629173','Alexandr Wang','アレクサンドル・ワン','AIライティング企業創業者','アレクサンドル・ワン（Alexandr Wang、1997年1月生まれ）は、アメリカの実業家・起業家。AIデータラベリングおよびモデル評価サービスを提供する企業Scale AIの共同創業者であり、2025年まで同社の最高経営責任者（CEO）を務めた。 2025年以降はMeta PlatformsのチーフAIオフィサー（Chief AI Officer）として同社のSuperintelligence Labsを統括する。2021年に24歳で世界最年少の自力億万長者となったことで広く知られる。','ja','アレクサンドル・ワン');
INSERT OR REPLACE INTO person VALUES ('1137062','Jack Ma','馬雲','中国の起業家','馬 雲（ば うん、マー・ユン、簡体字中国語: 马 云、拼音: Mǎ Yún、英語: Jack Ma〈ジャック・マー〉、1964年9月10日 - ）は、中国の起業家。現在、東京大学客員教授。アリババグループやアントグループの創業者・元CEO・元董事長（会長）、ソフトバンクグループ元取締役。浙江省杭州市出身。世界有数の企業家であり、中国本土の起業家で初めて『フォーブス』に名前が掲載された。','ja','馬雲');
INSERT OR REPLACE INTO person VALUES ('11395708','Takeshi Idezawa','出澤剛','日本の実業家 (1973-)','出澤 剛（いでざわ たけし、1973年〈昭和48年〉6月9日 - ）は、日本の実業家。LINEヤフー株式会社代表取締役社長CEO。','ja','出澤剛');
INSERT OR REPLACE INTO person VALUES ('114433732','Silvana Konermann','','Swiss-American biochemist','Silvana Konermann (born 1988) is a Swiss-American bioengineer and neuroscientist whose research focuses on CRISPR, genome engineering, transcription and epigenetics, and Alzheimer''s disease. She is an assistant professor of biochemistry at Stanford University and co-founder and executive director of Arc Institute.','en','Silvana Konermann');
INSERT OR REPLACE INTO person VALUES ('11453345','Ken Miyauchi','宮内謙','日本の実業家','宮内 謙（みやうち けん、1949年〈昭和24年〉11月1日 - ）は、日本の実業家。ソフトバンク株式会社代表取締役会長、Aホールディングス株式会社代表取締役社長、一般社団法人電気通信事業者協会会長、一般社団法人ブロードバンド推進協議会代表理事。愛媛県出身。','ja','宮内謙');
INSERT OR REPLACE INTO person VALUES ('11479322','Kentaro Kawabe','川邊健太郎','日本の企業経営者','川邊 健太郎（かわべ けんたろう、1974年〈昭和49年〉10月19日 - ）は、日本のメディアプロデューサー、実業家、ベンチャー起業家。東京都渋谷区恵比寿出身。千葉県館山市在住。2026年、「AIソロプレナー」として起業し、AI従業員と働いている。','ja','川邊健太郎');
INSERT OR REPLACE INTO person VALUES ('11529703','Yutaka Matsuo','松尾豊','日本の工学者','松尾 豊（まつお ゆたか、1975年〈昭和50年〉1月26日 - ）は、日本の工学者。東京大学大学院工学系研究科人工物工学研究センター／技術経営戦略学専攻 教授、東京大学新世代感染症センター メンバー。日本ディープラーニング協会理事長、ソフトバンクグループ社外取締役、内閣府「AI戦略会議」座長、新しい資本主義実現会議有識者構成員を務める。','ja','松尾豊');
INSERT OR REPLACE INTO person VALUES ('115662131','Tom B. Brown','トム・B・ブラウン','アメリカ合衆国の人工知能研究者・実業家','トム・B・ブラウン（Tom B. Brown）は、アメリカ合衆国の人工知能研究者・実業家。AIの安全性研究を専門とする企業Anthropicの共同創業者兼最高計算責任者（Chief Compute Officer, CCO）。 OpenAI在籍時に大規模言語モデルGPT-3の開発を主導した筆頭著者として知られ、深層強化学習における人間フィードバックからの強化学習（RLHF）の共同発明者でもある。','ja','トム・B・ブラウン');
INSERT OR REPLACE INTO person VALUES ('11624818','Susumu Fujita','藤田晋','日本の実業家','藤田 晋（ふじた すすむ、1973年〈昭和48年〉5月16日 - ）は、日本の実業家、馬主。株式会社サイバーエージェント代表取締役会長、株式会社AbemaTV代表取締役社長、株式会社ゼルビア代表取締役社長兼CEO、一般社団法人Mリーグ機構代表理事・チェアマン、一般社団法人新経済連盟副代表理事。 フォーブス誌によると2021年日本長者番付 RANKING TOP 50にて第33位にランクイン。資産額は1,944億円。','ja','藤田晋');
INSERT OR REPLACE INTO person VALUES ('116706551','Mira Murati','ミラ・ムラティ','OpenAIの暫定CEO (2023.11.17-2023.11.19)','ミラ・ムラティ（Mira Murati）は、アルバニア生まれ のエンジニアで経営者である。2018年からOpenAI Inc.の最高技術責任者を務めている。2023年11月17日～11月19日にOpenAI Inc.の暫定CEOに就任していた。','ja','ミラ・ムラティ');
INSERT OR REPLACE INTO person VALUES ('118289185','Thomas Wolf','','physicist, lawyer and computer scientist; natural language processing researcher; researcher, Hugging Face','','','');
INSERT OR REPLACE INTO person VALUES ('1193093','Takafumi Horie','堀江貴文','日本の実業家、著述家','堀江 貴文（ほりえ たかふみ、1972年〈昭和47年〉10月29日 - ）は、日本の実業家、著作家、投資家、タレント、俳優、歌手、馬主、料理人、ラジオパーソナリティ、政治活動家、参議院議員私設秘書、YouTuber。 愛称はホリエモン。堀江本人があだ名やペンネームなどを名乗る際には「たかぽん」を自称。SNS media&consulting株式会社ファウンダー、インターステラテクノロジズ株式会社ファウンダー、ゼロ高等学院主宰、株式会社7gogo取締役、日本ゴルフ改革会議委員、Jリーグアドバイザー、大阪府・大阪市の特別顧問（国際博覧会（万博）担当）、ライブドア（4代目）エグゼクティブ・アドバイザー、野菜アドバイザー、北九州市アドバイザー、北九州下関フェニックスオーナー、CROSS FM代表取締役会長、トキエア取締役、ホリエモンAI学校株式会社取締役、太洋物産取締役。 ライブドア（2代目）代表取締役社長CEO、エイシス代表取締役などを歴任した。ライブドア事件（後述）を起こしている。','ja','堀江貴文');
INSERT OR REPLACE INTO person VALUES ('119721378','Daniela Amodei','ダニエラ・アモデイ','AnthropicのPresident兼共同創設者','ダニエラ・アモデイ（英語: Daniela Amodei、1987年4月24日 - ）は、アメリカ合衆国の実業家・起業家。人工知能（AI）の安全性研究を行う企業Anthropicの共同創業者兼社長を務める。Anthropicは、大規模言語モデルのシリーズ「Claude」を開発していることで知られる。','ja','ダニエラ・アモデイ');
INSERT OR REPLACE INTO person VALUES ('120492201','Aravind Srinivas','アラビンド・スリニバス','AI研究者','アラヴィンド・スリニヴァス（Aravind Srinivas、1994年6月7日 - ）は、インド出身のコンピュータ科学者、実業家。AIを用いた回答エンジンを運営するPerplexity AIの共同創業者兼CEO。','ja','アラヴィンド・スリニヴァス');
INSERT OR REPLACE INTO person VALUES ('122903588','Ivan Zhao','','founder of Notion','Notionの共同創業者で、CEO。ブリティッシュコロンビア大学で認知科学を学び、Notionの前は、教育系スタートアップInklingでプロダクトデザイナーを務めた(Lenny’s Newsletterなどの紹介による)。','x','ivanhzhao');
INSERT OR REPLACE INTO person VALUES ('123125817','Ginger Luckey Gaetz','','sister of Palmer Luckey, wife of Matt Gaetz','','','');
INSERT OR REPLACE INTO person VALUES ('123130693','Jan Leike','ヤン・ライケ','AI safety researcher','ヤン・ライケ（Jan Leike、1986年または1987年生まれ）は、ドイツ出身のAIアラインメント研究者である。DeepMindおよびOpenAIでの研究を経て、2024年5月よりAnthropicのアラインメント科学チーム（Alignment Science Team）を共同でリードしている。人間のフィードバックによる強化学習（RLHF）の先駆的研究および超知能のアラインメントを目指した「スーパーアラインメント」構想の提唱者として広く知られる。','ja','ヤン・ライケ');
INSERT OR REPLACE INTO person VALUES ('123478068','Jakub Pachocki','','computer scientist','Jakub Pachocki (born 1991) is a Polish computer scientist and former competitive programmer. He is best known as OpenAI''s chief scientist and for his role in overseeing development of GPT-4.','en','Jakub Pachocki');
INSERT OR REPLACE INTO person VALUES ('123758735','Arthur Mensch','','French artificial intelligence researcher','Arthur Mensch (born 17 July 1992) is a French artificial intelligence researcher and entrepreneur, best known as the co-founder and CEO of the Paris-based AI company Mistral AI. He is one of the most prominent figures in Europe’s AI ecosystem and is often cited in debates on AI policy, sovereign technology, and open models. In 2025, Challenges ranked him among the 500 wealthiest French people. He was included in Time''s 100 Most Influential People in AI in 2024, being featured in the list among innovators.','en','Arthur Mensch');
INSERT OR REPLACE INTO person VALUES ('124213692','Lori Mills Huang','ロリ・フアン','co-founder of Jen-Hsun and Lori Huang Foundation, focusing on STEM education','Jen-Hsun "Jensen" Huang (born February 17, 1963) is a Taiwanese and American electrical engineer and businessman. He co-founded the technology company Nvidia, one of the world''s most valuable corporations, and served as its president and CEO from its founding in 1993 until his resignation in 2026. As of November 2026, Forbes estimates his net worth at US$141.9 billion, making him the thirteenth-wealthiest person in the world.','en','Jensen Huang');
INSERT OR REPLACE INTO person VALUES ('124429789','Brian Schimpf','','CEO of Anduril Industries','','','');
INSERT OR REPLACE INTO person VALUES ('124646741','Trae Stephens','','American arms dealer','Trae Stephens (born November 1983) is an American venture capitalist and entrepreneur. He is a co-founder and executive chairman of Anduril Industries, a defense technology company. He is a partner at Peter Thiel''s venture capital firm Founders Fund and an early Palantir employee. As of June 2025, Stephens is a billionaire.','en','Trae Stephens');
INSERT OR REPLACE INTO person VALUES ('125192446','Timothée Lacroix','','','','','');
INSERT OR REPLACE INTO person VALUES ('126287485','Mark Chen','','artificial intelligence researcher','OpenAIのChief Research Officer。2018年にOpenAIに入り、DALL·EやCodexなどの研究を率いた。以前はJane Streetでクオンツ・トレーダー。MITで数学とコンピュータサイエンスの学位を取った(Latent SpaceとMIT Technology Reviewの紹介による)。','x','markchen90');
INSERT OR REPLACE INTO person VALUES ('126287604','Simon Last','','co-founder and CTO, Notion','','','');
INSERT OR REPLACE INTO person VALUES ('12730959','Ion Stoica','','American computer scientist','Ion Stoica (born 1964 or 1965) is a Romanian–American computer scientist specializing in distributed systems, cloud computing and computer networking. He is a professor of computer science at the University of California, Berkeley and co-director of AMPLab. He co-founded Conviva and Databricks with other original developers of Apache Spark and Anyscale with other original developers of Ray.','en','Ion Stoica');
INSERT OR REPLACE INTO person VALUES ('127425804','Daisuke Okanohara','岡野原大輔','日本の実業家 (1982-)','Preferred Networks(PFN)の共同創業者で、代表取締役(2026年4月時点の紹介では代表取締役社長)。2006年に東京大学大学院在学中にPreferred Infrastructureを創業し、2014年にPFNを創業した。2010年に東京大学で情報理工学の博士号を取り、Matlantisの社長も務める。肩書きは時期や資料で表記が異なります(PFN公式の創業者メッセージなどによる)。','x','hillbig');
INSERT OR REPLACE INTO person VALUES ('127454','Miranda Kerr','ミランダ・カー','オーストラリアのファッションモデル','ミランダ・カー（Miranda Kerr、1983年4月20日 - ）は、オーストラリア出身の女性ファッションモデル、実業家。 アメリカのランジェリーブランド「ヴィクトリアズ・シークレット」の特別広告塔にあたる“エンジェル”の一員としての活動が最も著名。オーストラリア人初の“エンジェル”となった2007年から2012年まで同ブランドのショーの仕事を継続的にこなしてきたほか、テレビや雑誌など様々な分野で活躍してきた。シャネル・イマン、ドウツェン・クロース、アドリアナ・リマ等と並び立つ、著名な“ヴィクトリアズ・シークレットモデル”とされている。','ja','ミランダ・カー');
INSERT OR REPLACE INTO person VALUES ('12908','George Soros','ジョージ・ソロス','アメリカの投資家・投機家・慈善家','ジョージ・ソロス（英: George Soros、1930年8月12日 - ）は、ハンガリーブダペスト生まれのハンガリー系ユダヤ人の投資家、トレーダー。ウォーレン・バフェット、ジム・ロジャーズとともに世界三大投資家としてよく知られる。 天才投資家として知られ「イングランド銀行を潰した男」(The Man Who Broke the Bank of England) の異名を取る。 ソロス・ファンド・マネジメント (Soros Fund Management) 会長、オープン・ソサエティ財団 (Open Society Foundations; 旧称: Open Society Institute) 創設者、彼の生まれ故郷でもあるブダペストにある中央ヨーロッパ大学 (CEU) 共同創設者、Project Syndicate 出資者、シンクタンク Institute for New Economic Thinking (INET) 出資者及び創設者の一人である。投資家であると同時に政治運動家、政治経済に関する評論家としても活動している。','ja','ジョージ・ソロス');
INSERT OR REPLACE INTO person VALUES ('130487604','Daniel Levy','','artificial intelligence researcher','','','');
INSERT OR REPLACE INTO person VALUES ('131847088','Liang Wenfeng','梁文鋒','中華人民共和国の起業家 (1985-)。深度求索 (DeepSeek) のCEO','Liang Wenfeng (Chinese: 梁文锋; pinyin: Liáng Wénfēng; born 1985) is a Chinese entrepreneur and businessman who is the co-founder of the quantitative hedge fund High-Flyer, as well as the founder and CEO of its artificial intelligence company DeepSeek. Liang attended Zhejiang University, and began his career by applying machine learning methods to quantitative finance.','en','Liang Wenfeng');
INSERT OR REPLACE INTO person VALUES ('133538772','Nick Frosst','','Canadian computer scientist and musician','Nicholas Frosst (born January 5, 1993) is a Canadian computer scientist and musician. He co-founded Cohere, a Toronto-based artificial intelligence company. He is also the lead singer in the indie rock band Good Kid.','en','Nick Frosst');
INSERT OR REPLACE INTO person VALUES ('133848571','Ivan Zhang','','co-founder at Cohere','','','');
INSERT OR REPLACE INTO person VALUES ('135089578','Denis Yarats','','entrepreneur and computer scientist','Denis Yarats (born 1987) is a computer scientist and entrepreneur, best known as the co-founder and Chief Technology Officer (CTO) of Perplexity AI, an AI-powered search engine launched in 2022.','en','Denis Yarats');
INSERT OR REPLACE INTO person VALUES ('135111322','Jack Clark','ジャック・クラーク','イギリス出身の起業家、人工知能政策専門家、元テクノロジー・ジャーナリスト','ジャック・クラーク（Jack Clark、1987年頃 - ）は、イギリス出身の起業家、人工知能（AI）政策専門家、および元テクノロジー・ジャーナリストである。 AI安全性研究企業Anthropicの共同創設者として知られ、2026年3月よりAnthropicの公益担当責任者（Head of Public Benefit）を務める。Anthropic設立以前は、OpenAIにおいてポリシー・ディレクターを歴任した。また、AI研究の動向を分かりやすく解説する週刊ニュースレター「Import AI」の執筆者としても広く知られている。','ja','ジャック・クラーク (AI)');
INSERT OR REPLACE INTO person VALUES ('135487647','Saining Xie','','researcher','','','');
INSERT OR REPLACE INTO person VALUES ('13560771','Laura Arrillaga-Andreessen','','American philanthropist, educator, author','Laura K Arrillaga-Andreessen (born 26 Aug 1970) is an American author and philanthropist. She is married to tech billionaire Marc Andreessen. Born to wealthy parents, she became the founder and president of the Laura Arrillaga-Andreessen Foundation, a private philanthropic foundation that describes itself as a philanthropic "innovation lab", and founded the Silicon Valley Social Venture Fund (SV2), a venture philanthropy fund.','en','Laura Arrillaga-Andreessen');
INSERT OR REPLACE INTO person VALUES ('13560796','Ruchi Sanghvi','','Computer engineer','Ruchi Sanghvi (born 20 January 1982) is an Indian-American computer engineer and businesswoman. She was the first female engineer hired by Facebook. In late 2010, she quit Facebook and in 2011, she started her own company Cove, with two other co-founders. The company was sold to Dropbox in 2012 and Sanghvi joined Dropbox as VP of Operations. She left Dropbox in October 2013.','en','Ruchi Sanghvi');
INSERT OR REPLACE INTO person VALUES ('136430975','Jack Altman','ジャック・アルトマン','American investor','Jack Altman is an American businessman, entrepreneur, author, and venture capitalist. He is a general partner with the venture capital firm, Benchmark. Previously, he was the founder and managing partner of Alt Capital, and Hydrazine Capital with his brother Sam. Until 2023, he served as CEO of Lattice, a human resources software company he co-founded.','en','Jack Altman (investor)');
INSERT OR REPLACE INTO person VALUES ('136430980','','','スタンダップコメディアン','','','');
INSERT OR REPLACE INTO person VALUES ('136908316','Matt Danzeisen','','American financier and investor','Charles Matthew Danzeisen (born c. 1977) is an American financier and investor. He was vice president of BlackRock before becoming portfolio manager at Thiel Capital in 2008. He is active in Asia and Asia-Pacific. Danzeisen is co-founder of Crescendo Equity Partners. In 2017, he married Peter Thiel.','en','Matt Danzeisen');
INSERT OR REPLACE INTO person VALUES ('137189639','Susan Dell','','American philanthropist','Susan Lynn Lieberman Dell (née Lieberman) is an American businesswoman, philanthropist, and the wife of Michael Dell. They married in 1989, four years after he formed his eponymous computer company. She is the co-founder and current chair of the Michael & Susan Dell Foundation.','en','Susan Dell');
INSERT OR REPLACE INTO person VALUES ('1373397','James H. Clark','ジェームズ・クラーク','American entrepreneur and computer scientist','ジム・クラーク（James H. Clark、1944年3月23日 - ）は、アメリカ合衆国の実業家。','ja','ジェームズ・クラーク (事業家)');
INSERT OR REPLACE INTO person VALUES ('137910729','Nathan Gettings','','co-founder of Palantir','Nathan Dale Gettings is a software engineer and entrepreneur who has served as co-founder and CTO of Palantir Technologies, co-founder and CEO of RoboteX, co-founder and chief risk officer at Affirm Holdings, and chief data advisor to Leeo, Inc.','en','Nathan Gettings');
INSERT OR REPLACE INTO person VALUES ('138076','Yuri Milner','ユーリイ・ミルナー','Russian entrepreneur and physicist','ユーリ・ミルナー（英語: Yuri Milner、ロシア語: Ю́рий Ми́льнер、1961年11月11日 - ）はソ連生まれの物理学者・投資家・資産家(億万長者)で、おもにシリコンバレーで先端技術関係に投資している。ロシア語読みでユーリー・ミリネルとも。2012年にグーグルの共同創業者セルゲイ・ブリン、フェイスブックの創業者のマーク・ザッカーバーグ、中国人起業家のジャック・マーらと自然科学研究者らを賞与するブレイクスルー賞を設立した。ロシア系ユダヤ人。','ja','ユーリ・ミルナー');
INSERT OR REPLACE INTO person VALUES ('139553124','','','','','','');
INSERT OR REPLACE INTO person VALUES ('140342511','Oliver Mulherin','','Australian software engineer','','','');
INSERT OR REPLACE INTO person VALUES ('140527842','Clement Delangue','','French data scientist','Hugging Face, Inc., is an American company based in New York City. Its online platform allows users to share datasets and machine learning models. It also develops open-source machine learning libraries, notably the Transformers library. Hugging Face agreed to an acquisition by Nvidia in August 2026.','en','Hugging Face');
INSERT OR REPLACE INTO person VALUES ('140533344','','','French mathematician, chief technology officer of Hugging Face','Hugging Face, Inc., is an American company based in New York City. Its online platform allows users to share datasets and machine learning models. It also develops open-source machine learning libraries, notably the Transformers library. Hugging Face agreed to an acquisition by Nvidia in August 2026.','en','Hugging Face');
