INSERT OR REPLACE INTO person VALUES ('14251045','Lucinda Southworth','','','','','');
INSERT OR REPLACE INTO person VALUES ('149067','Pavel Durov','パーヴェル・ドゥーロフ','ロシアの実業家','パーヴェル・ヴァレリーヴィッチ・ドゥーロフ（ロシア語: Па́вел Вале́рьевич Ду́ров, 1984年10月10日 - ）は、ロシアの起業家。SNSのVK、インスタントメッセージアプリケーションのTelegramの創設者として知られる。パーヴェルはニコライ・ドゥーロフの弟にあたる。2014年にVKのCEOから追放されて以来、ドゥーロフ兄弟はセントクリストファー・ネイビス市民で、自主的な亡命者として世界中を旅してきた。2017年にはフィンランド代表として世界経済フォーラム (WEF) のヤンググローバルリーダーズに参加した。','ja','パーヴェル・ドゥーロフ');
INSERT OR REPLACE INTO person VALUES ('1521908','Marc Benioff','マーク・ベニオフ','アメリカ合衆国の起業家','マーク・ラッセル・ベニオフ（Marc Russell Benioff、1964年9月25日 - ）は、アメリカ合衆国のインターネット起業家である。企業向けクラウドサービス企業であるセールスフォース・ドットコム（現・セールスフォース）の創業者であり、会長兼CEOである。2020年6月現在、セールスフォースの株式の3.36％を保有しており、時価総額は48億ドルである。2020年5月時点での純資産額は71億ドルである。','ja','マーク・ベニオフ');
INSERT OR REPLACE INTO person VALUES ('15439301','Evan Spiegel','エヴァン・スピーゲル','American businessman (born 1990)','エヴァン・シュピーゲル（エヴァン・トーマス・シュピーゲル、Evan Thomas Spiegel 、1990年6月4日 - ）は、アメリカ合衆国の実業家であり、モバイルアプリケーション Snapchat を保有する Snap Inc. の共同創業者にして最高経営責任者。','ja','エヴァン・シュピーゲル');
INSERT OR REPLACE INTO person VALUES ('15731400','Arash Pournouri','アーラシュ・ポアノウリ','Iranian-Swedish record manager, record producer, songwriter and record executive','Arash Andreas Pournouri (born 28 August 1981) bka Ash Pournouri is an Iranian-Swedish record producer, music executive, and businessman.','en','Ash Pournouri');
INSERT OR REPLACE INTO person VALUES ('1586871','Bill Ackman','ビル・アックマン','アメリカの投資家、ヘッジファンドのマネージャー','ウィリアム・アルバート・アックマン（William Albert Ackman、1966年5月11日 - ）は、アメリカのビリオネアのヘッジファンドマネージャーである。 ヘッジファンド管理会社パーシング・スクエア・キャピタル・マネジメントの設立者でCEOを務めている。彼の投資方法により、投資活動家として活動している。フォーブスによると、2024年6月 (2024-06)現在、アックマンの純資産は推定93億ドルである。 アックマンは慈善家であり、ギビング・プレッジにより、人生の終わりまでに富の少なくとも50％を寄付することを約束している。 アックマンは長年民主党の候補者や組織へ寄付をしてきたが、支援していたフィリップスが選挙から撤退したことを受け、 ロバート・ケネディ・ジュニアの選挙キャンペーンに寄付を行い、2024年のアメリカ合衆国大統領選挙ではドナルド・トランプを支持するようになった。アックマンは、ガザ戦争におけるイスラエルの行動に対して公に支持を表明し、イスラエル当局の声明を非難する書簡に署名したハーバード大学の学生たちの名前を公表するように要求した。 女優の松居一代は友人。','ja','ビル・アックマン');
INSERT OR REPLACE INTO person VALUES ('16186882','Wendy Schmidt','','philanthropist','Wendy Susan Schmidt (née Boyle) is an American philanthropist and investor. She is the president and co-founder of the Schmidt Family Foundation, holding over $2 billion in philanthropic assets, and Schmidt Ocean Institute. She is married to Eric Schmidt, the former CEO of Google.','en','Wendy Schmidt');
INSERT OR REPLACE INTO person VALUES ('162005','Paul Allen','ポール・アレン','アメリカの実業家 (1955-2018)','ポール・ガードナー・アレン（Paul Gardner Allen, 1953年1月21日 - 2018年10月15日）は、アメリカ合衆国の実業家、マイクロソフト社共同創業者。1983年に退社し、1990年に復帰するが、2000年に再び退社、取締役も退任。その後は資産運用や投資を業務とするバルカン社を経営した。 マイクロソフト社をビル・ゲイツと共に創業し、大資産家として知られており、2017年時点の資産205億ドル（2兆2500億円）、6つの財団を傘下に率いるポール・G・アレン財団を運営している。また、アレン脳科学研究所や音楽史美術館Experience Music Projectなど様々な事業に出資や寄付をしている。SF ファンとしても知られ、私財を投じて SF博物館Science Fiction Museum and Hall of Fameを設立したほか、SETI協会にも多額の寄付を行っており、アレンの名を冠した電波望遠鏡アレン・テレスコープ・アレイの建造も進められている。','ja','ポール・アレン');
INSERT OR REPLACE INTO person VALUES ('16204157','Stephen Cohen','スティーヴン・コーエン (起業家)','American computer scientist and entrepreneur','Stephen Andrew Cohen (born September 30, 1982) is an American computer scientist and entrepreneur best known as a co-founder, president and secretary of Palantir Technologies, a platform for analyzing integration and visualizing data used by governments and businesses. He is credited with creating the initial prototype of Palantir in eight weeks. Since then, he has interviewed over 4,500 candidates and continues to be actively involved in Palantir.','en','Stephen Cohen (entrepreneur)');
INSERT OR REPLACE INTO person VALUES ('16233063','John Collison','ジョン・コリソン','Irish businessman','ジョン・コリソン（John Collison、1990年8月6日 - ）は、アイルランドの起業家であり、決済システムを提供する Stripe の共同創業者。2017年に兄パトリック・コリソンと共に世界長者番付に純資産11億ドルで掲載され、最年少のビリオネアとなった。','ja','ジョン・コリソン');
INSERT OR REPLACE INTO person VALUES ('16269109','Palmer Luckey','パーマー・ラッキー','American founder of Oculus VR and inventor of the Oculus Rift','Palmer Freeman Luckey (born September 19, 1992) is an American entrepreneur and co-founder of defense technology company Anduril Industries. He was the founder of Oculus VR and designer of the Oculus Rift, a virtual reality headset that is widely credited with reviving the virtual reality industry. In 2017, Luckey co-founded Anduril Industries, a military technology company focused on autonomous drones and sensors for military applications.','en','Palmer Luckey');
INSERT OR REPLACE INTO person VALUES ('1668164','Scott McNealy','スコット・マクネリ','American businessman','スコット・マクネリ（Scott G. McNealy, 1954年11月13日 - ）は、アメリカ合衆国の実業家。米サン・マイクロシステムズ社の共同設立者の一人。','ja','スコット・マクネリ');
INSERT OR REPLACE INTO person VALUES ('16847797','Mustafa Suleyman','ムスタファ・シュリーマン','British entrepreneur (born 1984)','Mustafa Suleyman (born in August 1984) is a British artificial intelligence (AI) entrepreneur. He is the CEO of Microsoft AI, and the co-founder and former head of applied AI at DeepMind, an AI company which was acquired by Google. After leaving DeepMind, he co-founded Inflection AI, a machine learning and generative AI company, in 2022.','en','Mustafa Suleyman');
INSERT OR REPLACE INTO person VALUES ('16887186','Matei Zaharia','','Romanian-Canadian computer scientist and engineer','Matei Zaharia (born 1984 or 1985) is a Romanian-Canadian computer scientist, educator businessman. He is the creator of Apache Spark and the chief technology officer, one of the founders of Databricks and has developed open-source projects like Delta Lake, MLflow and Omnigent. In 2026, Forbes ranked him and Ion Stoica as the richest Romanians, with a net worth of $5 billion each.','en','Matei Zaharia');
INSERT OR REPLACE INTO person VALUES ('18165291','Joseph Tsai','ジョセフ・ツァイ','businessman','Joseph Chung-Hsin Tsai (Chinese: 蔡崇信; pinyin: Cài Chóngxìn; born January 19, 1964) is a Taiwanese and Canadian billionaire business executive, lawyer, and philanthropist. He is a co-founder and the chairman of the Chinese technology company Alibaba Group.','en','Joseph Tsai');
INSERT OR REPLACE INTO person VALUES ('18207172','Lisa Su','リサ・スー','American business executive and electrical engineer','リサ・スー（Lisa Su、蘇 姿豊、そ しほう、繁体字: 蘇 姿豐、注音: ㄙㄨ ㄗ ㄈㄥ、1969年11月7日 - ）は、台湾系アメリカ人の経営者、半導体技術者で、アドバンスト・マイクロ・デバイス（AMD）の最高経営責任者（CEO）、会長（Chair）である。IBMの半導体研究開発センターではディレクターとしてPowerPC開発、副社長時代にはSOIの開発とCell Broadband Engineを開発に携わったことで知られている。','ja','リサ・スー');
INSERT OR REPLACE INTO person VALUES ('18263','Gina Bianchini','','American businesswoman','Gina Bianchini (born 1972) is an American entrepreneur and investor. She is the Founder & CEO of Mighty Networks.','en','Gina Bianchini');
INSERT OR REPLACE INTO person VALUES ('18341330','Marc Randolph','マーク・ランドルフ','American tech entrepreneur and co-founder of Netflix','Marc Bernays Randolph (born April 29, 1958) is an American tech entrepreneur, advisor and speaker. He is the co-founder and first CEO of Netflix. A serial entrepreneur who is said to have helped found the U.S. edition of Macworld magazine and the computer mail-order businesses MacWarehouse and MicroWarehouse, Randolph now serves on the boards of Looker Data Sciences and Chubbies Shorts. He previously served on the boards of Getable, Rafter, ReadyForce.','en','Marc Randolph');
INSERT OR REPLACE INTO person VALUES ('19364797','Daniel Gross','','businessman','Daniel Gross (Hebrew: דניאל גרוס) is an Israeli-American businessman who co-founded Cue, led artificial intelligence efforts at Apple, served as a partner at Y Combinator, and is a notable technology investor in companies such as Uber, Instacart, Figma, GitHub, Airtable, Rippling, CoreWeave, Character.ai, Perplexity AI, and others. In June 2024, he co-founded Safe Superintelligence Inc. Time 100 has listed Gross as one of the "Most Influential People in AI".','en','Daniel Gross (businessman)');
INSERT OR REPLACE INTO person VALUES ('19538950','Nathan Blecharczyk','','American businessman & Co-founder of Airbnb','Nathan Blecharczyk (; born 1983) is the co-founder and chief strategy officer (CSO) of Airbnb, and chairman of Airbnb China. Blecharczyk was also the company''s first chief technology officer. Blecharczyk is the 203rd richest person in the world according to Forbes, with a net worth of $9.4 billion, mostly due to his ownership of 62 million shares of Airbnb.','en','Nathan Blecharczyk');
INSERT OR REPLACE INTO person VALUES ('19560551','Joe Gebbia','ジョー・ゲビア','American businessman and a co-founder of Airbnb','Joseph Gebbia Jr. (; born August 21, 1981) is an American designer and entrepreneur, and a co-founder of Airbnb. In 2025, he joined the Department of Government Efficiency (DOGE). Gebbia was appointed by President Donald Trump as the first Chief Design Officer to lead the National Design Studio. Gebbia is also on the board of directors of Airbnb, but has not been involved in the operations of the company since 2022. In 2022, Gebbia joined the board of Tesla Inc.','en','Joe Gebbia');
INSERT OR REPLACE INTO person VALUES ('19560940','Alex Karp','アレックス・カープ','businessman, author','アレクサンダー・カープ（英: Alexander Caedmon Karp、1967年10月2日 - ）は、アメリカ合衆国の億万長者、実業家。ソフトウェア会社パランティア・テクノロジーズの共同設立者兼CEO。2024年2月現在、彼の推定純資産は19億米ドルである。','ja','アレックス・カープ');
INSERT OR REPLACE INTO person VALUES ('19561225','Lip-Bu Tan','リップ＝ブー・タン','American businessman','Lip-Bu Tan (born November 12, 1959) is an American business executive who has been chief executive officer (CEO) of Intel since 2025. He is also chairman of Walden International, a venture capital firm; a founding managing partner of Walden Catalyst Ventures and Celesta Capital; and holds numerous board positions. Tan was CEO of Cadence Design Systems from 2009 to 2021.','en','Lip-Bu Tan');
INSERT OR REPLACE INTO person VALUES ('19663471','Bobby Murphy','ボビー・マーフィー','American businessman (born 1988)','ボビー・マーフィー（ボビー・コーネリウス・ゴー・マーフィー、Robert Cornelius Go Murphy 、1988年7月19日 - ）は、アメリカ合衆国の起業家、エンジニアであり、モバイルアプリケーション「Snapchat」を保有する「Snap Inc.」の共同創業者にして最高技術責任者。','ja','ボビー・マーフィー');
INSERT OR REPLACE INTO person VALUES ('20684647','Tobias Lütke','トビアス・リュトケ','German entrepreneur and software developer','Tobias Lütke (born 1980) is a German Canadian entrepreneur and racing driver who is the co-founder and CEO of Shopify, an e-commerce company based in Ottawa, Ontario, Canada. He competes in the 2025 IMSA SportsCar Championship driving in LMP2 for Era Motorsport. Lütke has been part of the core team of the Ruby on Rails framework and has created open source libraries such as Active Merchant. As of 2022, he was the 11th richest Canadian.','en','Tobias Lütke');
INSERT OR REPLACE INTO person VALUES ('2069573','Anne Wojcicki','アン・ヴォジツキ','American biotech analyst, biologist, businesswoman, and co-founder of 23andMe','Anne E. Wojcicki ( woo-CHITS-kee; born July 28, 1973) is an American entrepreneur who co-founded the personal genomics company 23andMe.','en','Anne Wojcicki');
INSERT OR REPLACE INTO person VALUES ('20900227','Priscilla Chan','プリシラ・チャン','American pediatrician and philanthropist','プリシラ・チャン(Priscilla Chan、1985年2月24日 - ）は、アメリカ合衆国の小児科医、慈善活動家である。夫は、Facebook共同創設者の1人でMeta最高経営責任者 (CEO) のマーク・ザッカーバーグ。中国系アメリカ人。 生まれも育ちもマサチューセッツ州である。学部はハーバード大学に通い、その後カリフォルニア大学サンフランシスコ校で医学博士号を取得した。 2015年12月、チャンとザッカーバーグは保有するFacebook株の99パーセント（450億ドル相当）を、福祉と教育を主眼とした慈善団体チャン・ザッカーバーグ・イニシアチヴに寄付することを発表した。2016年、2人はさらに46億ドルを慈善活動に使うことを約束している。','ja','プリシラ・チャン (慈善家)');
INSERT OR REPLACE INTO person VALUES ('21063274','Brendan Iribe','ブレンダン・イリベ','American game programmer and founder','Brendan Trexler Iribe (; born August 12, 1979) is an American game programmer, racing driver, entrepreneur and co-founder of Oculus VR, Inc. and Scaleform. He is the managing partner at BIG Ventures, an early-stage venture fund.','en','Brendan Iribe');
INSERT OR REPLACE INTO person VALUES ('211098','Reid Hoffman','リード・ギャレット・ホフマン','アメリカ合衆国の起業家、ベンチャー資本家','リード・ギャレット・ホフマン（Reid Garrett Hoffman、1967年8月5日 - ）は、アメリカ合衆国の起業家、ベンチャー資本家、著作家。事業用SNSのLinkedInの共同創業者として知られる。PayPalの創業期チームの一員であり、いわゆる「ペイパル・マフィア」の中心人物のひとり。グレイロック・パートナーズのパートナー（2009年~）。Microsoft取締役（2017年~）。Inflection AI（2022年共同創業）、Manas AI（2025年共同創業）の創業者でもある。 2025年10月時点の推定資産は約25億ドル。少なくとも2011年よりビルダーバーグ会議の会員であり、2015年よりアメリカ合衆国の外交問題評議会の会員。','ja','リード・ギャレット・ホフマン');
INSERT OR REPLACE INTO person VALUES ('21712134','Ilya Sutskever','イリア・スーツキヴァー','AIの研究者','イリヤ・サツケバー（Ilya Sutskever, 1986年12月8日 - ） は、機械学習を専門とするコンピューター科学者である。 サツケバーは、深層学習の分野において、いくつかの主要な貢献を果たしてきた。特に、アレックス・クリジェフスキーおよびジェフリー・ヒントンと共に、畳み込みニューラルネットワークであるAlexNetの共同発明者である。 なお、日本語ではイリア・スツケヴァーとも表記される。','ja','イリヤ・サツケバー');
INSERT OR REPLACE INTO person VALUES ('218630','Michael Dell','マイケル・デル','アメリカの実業家','マイケル・ソール・デル（英語: Michael Saul Dell, 1965年2月23日 - ）は、アメリカ合衆国の実業家。デル・テクノロジーズの創設者にして会長兼最高経営責任者。','ja','マイケル・デル');
INSERT OR REPLACE INTO person VALUES ('22063678','Anjali Pichai','アンジャリ・ピチャイ','American chemical engineer','Pichai Sundararajan (born June 10, 1972), better known as Sundar Pichai, is an Indian–American business executive who has been the CEO of Google since 2015 and the CEO of its parent company Alphabet Inc. since 2019. Pichai began his career as a materials engineer.','en','Sundar Pichai');
INSERT OR REPLACE INTO person VALUES ('22095663','Holden Karnofsky','ホールデン・カルノフスキー','American nonprofit executive','ホールデン・G・カルノフスキー（英語: Holden G. Karnofsky、1980年または1981年生まれ）は、アメリカ合衆国の非営利団体経営者、フィランソロピスト、AI安全研究者。慈善評価機関GiveWellの共同創設者であり、助成財団オープン・フィランソロピー（現・コエフィシェント・ギビング）の共同創設者・元CEOとして知られる。 2025年よりAnthropicの技術スタッフ。 効果的利他主義運動において最も影響力ある人物の一人とされ、AI安全・長期主義・慈善配分の方法論において独自の思想体系を構築してきた。','ja','ホールデン・カルノフスキー');
INSERT OR REPLACE INTO person VALUES ('22120737','Shintaro Yamada','山田進太郎','日本の実業家','山田 進太郎(やまだ しんたろう、1977年9月21日 - )は、日本の起業家、実業家、投資家。メルカリ創業者、同取締役兼代表執行役CEO(社長)。2021年7月より公益財団法人山田進太郎D&I財団の設立者兼代表理事。 フォーブス誌によると、2019年3月時点の総資産は1440億円で、日本長者番付33位。2022年版「長者番付」では8位にランクインしている。','ja','山田進太郎');
INSERT OR REPLACE INTO person VALUES ('22244566','Adda Quinn','','','','','');
INSERT OR REPLACE INTO person VALUES ('22244570','Nancy Wheeler Jenkins','','','','','');
INSERT OR REPLACE INTO person VALUES ('22244572','Barbara Boothe','','','','','');
INSERT OR REPLACE INTO person VALUES ('22276668','Arielle Zuckerberg','アリエル・ザッカーバーグ','','','','');
INSERT OR REPLACE INTO person VALUES ('22276670','Donna Zuckerberg','','American classicist, editor-in-chief of Eidolon','Donna Zuckerberg (born 1987) is an American classicist and author. She is author of the book Not All Dead White Men (2018), about the appropriation of classics by misogynist groups on the Internet. She was editor-in-chief of Eidolon, a classics journal, until its closure in 2020. She is a sister of Facebook co-founder and CEO Mark Zuckerberg.','en','Donna Zuckerberg');
INSERT OR REPLACE INTO person VALUES ('22278829','Shane Legg','シェーン・レッグ','machine learning researcher','Shane Legg (born 1973 or 1974) is a New Zealand machine learning researcher and entrepreneur. With Demis Hassabis and Mustafa Suleyman, he cofounded DeepMind Technologies (later bought by Google and now called Google DeepMind), and works there as the chief AGI scientist. He is also known for his academic work on artificial general intelligence, including his thesis supervised by Marcus Hutter.','en','Shane Legg');
INSERT OR REPLACE INTO person VALUES ('22568398','Karen Taylor','','','','','');
INSERT OR REPLACE INTO person VALUES ('23011253','Zhang Ying','キャシー・チャン','ジャック・マー（馬雲）の妻','','','');
INSERT OR REPLACE INTO person VALUES ('23016890','Ali Ghodsi','','Iranian-Swedish computer scientist','Ali Ghodsi (born 1978) is an Iranian-Swedish-American computer scientist and entrepreneur, specializing in distributed systems, big data and data management. He is a co-founder and CEO of Databricks and an adjunct professor at UC Berkeley. He co-authored several influential papers, including Apache Mesos and Apache Spark SQL. Ghodsi holds a PhD in computer science.','en','Ali Ghodsi');
INSERT OR REPLACE INTO person VALUES ('23417057','Garry Tan','','Venture capitalist','Garry Tan (Chinese: 陳嘉興; pinyin: Chén Jiāxìng; Pe̍h-ōe-jī: Tân Ka-heng; born 1981) is a Canadian-American venture capitalist who is the CEO of the startup accelerator Y Combinator and a founder of the venture capital fund Initialized Capital. He previously co-founded Posterous and Posthaven. He was an early employee at Palantir Technologies, and previously a partner at Y Combinator. Tan is also known for his engagement in San Francisco politics, both as a commenter on social media and as a political donor.','en','Garry Tan');
INSERT OR REPLACE INTO person VALUES ('23784752','Mark Bezos','マーク・ベゾス','Co-Founder & Partner of HighPost Capital','Marcus Jim Bezos ( BAY-zohss; born c. 1967) is an American space tourist and former advertising executive. He is the half-brother of Jeff Bezos, the founder of Amazon, with whom he flew to the edge of space as part of the Blue Origin NS-16 mission on July 20, 2021.','en','Mark Bezos');
INSERT OR REPLACE INTO person VALUES ('23795888','Jason Fried','ジェイソン・フリード','software entrepreneur','37signals (formerly Basecamp before reverting to its original name) is an American web software company based in Chicago, Illinois. The firm was co‑founded in 1999 by Jason Fried, Carlos Segura, and Ernest Kim as a web design company. Since mid‑2004, the company''s focus has shifted from web design to web application development. Its first commercial application was Basecamp, followed by Backpack, Campfire, and Highrise.','en','37signals');
INSERT OR REPLACE INTO person VALUES ('24803072','Greg S. Corrado','','machine learning scientist','','','');
INSERT OR REPLACE INTO person VALUES ('24894891','Rajeev Misra','ラジーブ・ミスラ','banker and executive based in London','ラジーブ・ミスラ（Rajeev Misra、1962年 - ）はアメリカ合衆国の実業家。ソフトバンクグループの米国戦略子会社Softbank Internet and Media, Inc.(SIMI)の戦略的ファイナンス責任者。ソフトバンク・ビジョン・ファンド設立のプロジェクトを主導。','ja','ラジーブ・ミスラ');
INSERT OR REPLACE INTO person VALUES ('265852','Tim Cook','ティム・クック','アメリカの企業経営者','“ティム”ティモシー・ドナルド・クック（Timothy Donald "Tim" Cook、1960年11月1日 - ）は、アメリカ合衆国の経営者。現在、Appleの取締役会長。同社最高経営責任者（CEO）を2011年から15年間にわたって務めたほか、2005年よりナイキの社外取締役も務める。 『フォーブス』誌の「世界で最も影響力のある人物」リストでは、2018年に24位に選ばれている。','ja','ティム・クック');
INSERT OR REPLACE INTO person VALUES ('26703258','Reynold Xin','','Computer scientist and engineer','Reynold Xin is a computer scientist, engineer, and entrepreneur specializing in big data, distributed systems, and cloud computing. He is a co-founder and Chief Architect of Databricks. He is best known for his work on Apache Spark, a leading open-source Big Data project.','en','Reynold Xin');
INSERT OR REPLACE INTO person VALUES ('26924676','Anthony Levandowski','','French-American automobile engineer (born 1980)','Anthony Levandowski (born March 15, 1980) is a French-American, self-proclaimed self-driving car engineer. In 2009, Levandowski co-founded Google''s self-driving car program, known as Waymo, and was a technical lead until 2016. In 2010, he co-founded Google X along with Yoky Matsuoka and Sebastian Thrun. In 2016, he co-founded and sold Otto, an autonomous trucking company, to Uber Technologies.','en','Anthony Levandowski');
INSERT OR REPLACE INTO person VALUES ('269309','Talulah Riley','タルラ・ライリー','イギリスの女優','タルラ・ライリー（Talulah Riley, 1985年9月26日 - ）は、イギリスの女優、映画監督、脚本家。','ja','タルラ・ライリー');
INSERT OR REPLACE INTO person VALUES ('2744012','Bob Miner','','American businessman (1941-1994)','Robert Nimrod Miner (December 23, 1941 – November 11, 1994) was an American businessman. He was the co-founder of Oracle Corporation and the producer of Oracle''s relational database management system. From 1977 until 1992, Miner led product design and development for the Oracle relational database management system. In December 1992, he left that role and spun off a small, advanced technology group within Oracle. He was an Oracle board member until October 1993.','en','Bob Miner');
INSERT OR REPLACE INTO person VALUES ('2846695','Andrew Y. Ng','アンドリュー・ング','American artificial intelligence researcher','アンドリュー・ヤン＝タック・ン（英語: Andrew Yan-Tak Ng、中国語: 吳恩達、1976年4月18日 - ）は、中国系アメリカ人の計算機科学者、人工知能研究者、投資家、起業家、Google Brainの共同設立者、 Baiduの元副社長兼チーフサイエンティスト、スタンフォード大学 兼担教授である。 EラーニングサービスのCourseraとdeeplearning.aiとAI Fundの創始者でもある。深層学習の分野でGPUの活用を提唱した。','ja','アンドリュー・ン');
INSERT OR REPLACE INTO person VALUES ('28839527','Pascale Fung','','研究者','Pascale Fung (馮雁) (born in Shanghai, China) is a co-founder and Chief Research and Innovation Officer of AMI Labs, an artificial intelligence research company focused on world models. She is a professor in the Department of Electronic & Computer Engineering and the Department of Computer Science & Engineering at the Hong Kong University of Science & Technology (HKUST). She is the director of the Centre for AI Research (CAiRE) at HKUST.','en','Pascale Fung');
INSERT OR REPLACE INTO person VALUES ('29043123','Quoc Viet Le','','研究者','Lê Viết Quốc (born 1982), or in anglicized form Quoc Viet Le, is a Vietnamese-American computer scientist and artificial intelligence researcher. He is a Google Fellow at Google DeepMind and a founding member of the Google Brain project. Le is best known for his pioneering work in deep learning, particularly in large-scale unsupervised learning, sequence-to-sequence (seq2seq) models, and AutoML (neural architecture search).','en','Quoc V. Le');
INSERT OR REPLACE INTO person VALUES ('29221954','Koray Kavukcuoglu','','Turkish ‪artificial intelligence researcher','GoogleのChief AI Architect(上級副社長)。Google DeepMindのCTOとして、Geminiの開発を率いた。2025年6月に、GoogleがChief AI Architectの役を新設し、就任した(Semaforの報道による)。役職は変わることがあるので、Googleの公式ページもご確認ください。','x','koraykv');
INSERT OR REPLACE INTO person VALUES ('292708','Randi Zuckerberg','ランディ・ザッカーバーグ','American businesswoman','Randi Jayne Zuckerberg (born February 28, 1982) is an American businesswoman. She is the former director of market development and spokesperson for Facebook, and a sister of the company''s co-founder and CEO Mark Zuckerberg. She currently hosts Randi Zuckerberg Means Business on SiriusXM on Wednesdays.','en','Randi Zuckerberg');
INSERT OR REPLACE INTO person VALUES ('3022141','Demis Hassabis','デミス・ハサビス','イギリスの人工知能研究者 (1976-)','デミス・ハサビス (Demis Hassabis, 1976年7月27日-）はイギリスの人工知能研究者、神経科学者（脳科学者）、企業家、コンピュータゲームデザイナー、世界的なゲームプレイヤーである。 Google DeepMindおよびIsomorphic Labs の最高経営責任者（CEO）兼共同創業者であり、英国政府のAI顧問も務めている。 AI技術（AlphaFold）を用いたタンパク質構造予測技術の研究により、2024年にデイヴィッド・ベイカー、ジョン・M・ジャンパーとともにノーベル化学賞を受賞した。','ja','デミス・ハサビス');
INSERT OR REPLACE INTO person VALUES ('305177','Jensen Huang','ジェンスン・フアン','台湾系アメリカ人の企業家、実業家 (1963 - )','ジェンスン・フアンまたはジェンスン・ファン（英: Jen-Hsun "Jensen" Huang、繁: 黃 仁勳、こうじんくん、1963年2月17日 - ）は、台湾系アメリカ人の起業家、実業家。グラフィック・プロセッサ会社のNVIDIAを共同設立し、社長兼CEOを務めた。 フォーブズの推計によると、2026年時点で純資産額は約1500億ドルと推定しており、世界で7番目に裕福な人物である。 NVIDIAは彼による経営下で、AIブームの中で急成長を遂げ、2025年10月には時価総額が5兆ドルを突破した初の企業となった。2021年と2024年には、タイム誌がファンを「最も影響力のある人物」に選出した。2025年には、同誌の「パーソン・オブ・ザ・イヤー」において、「人工知能(AI)の設計者たち」の一人として名を連ねた。','ja','ジェンスン・フアン');
INSERT OR REPLACE INTO person VALUES ('3124567','Michael Moritz','マイケル・モリッツ','Welsh venture capitalist','マイケル・モリッツ（Sir Michael Moritz KBE、1954年9月12日 - ）は、イギリス・ウェールズ出身のベンチャーキャピタリスト。米セコイア・キャピタルのチェアマンであり、Googleの前取締役。','ja','マイケル・モリッツ');
INSERT OR REPLACE INTO person VALUES ('312556','Jeff Bezos','ジェフ・ベゾス','アメリカの実業家 (1964-)','ジェフリー・プレストン・ジョーゲンセン（Jeffrey Preston Jorgensen、1964年1月12日 - 、プロとしてはジェフ・ベゾス (Jeff Bezos) としてよく知られている）は、アメリカ合衆国の実業家、投資家、フィランソロピスト。Amazon.comの共同創設者、取締役会長。 ジェフ・ベイゾスとも。 世界最大級の資産家の1人であり、フォーブスの長者番付によると2020年時点で2046億ドルの資産を有する。世界で初めて資産が2000億ドルを超えた人物。2013年に米有力新聞ワシントン・ポストを買収しオーナーとなった。','ja','ジェフ・ベゾス');
INSERT OR REPLACE INTO person VALUES ('312663','Eduardo Saverin','エドゥアルド・サベリン','シンガポール在住のブラジル人起業家','エドゥアルド・ルイス・サベリン（Eduardo Saverin、1982年3月19日 - ）はブラジルサンパウロ生まれのブラジル系アメリカ人起業家であり、マーク・ザッカーバーグほかとのFacebook共同設立者である。2011年1月4日現在、Facebookの株式の5%、25億ドルを所有している。','ja','エドゥアルド・サベリン');
INSERT OR REPLACE INTO person VALUES ('317521','Elon Musk','イーロン・マスク','アメリカの実業家、エンジニア (1971-)','イーロン・リーヴ・マスク（英語: Elon Reeve Musk、1971年6月28日 - ）は、南アフリカ共和国出身のアメリカ合衆国の起業家。2025年以降、第2次トランプ政権下で、公式には特別政府職員の職位で大統領であるドナルド・トランプの大統領上級政治顧問の役割を務め、政府効率化省（DOGE）の事実上のトップとして活動した。PayPal、スペースX、テスラ、ボーリング・カンパニー、OpenAI、xAI等を共同設立し、スペースX、テスラのCEO、X社（旧：Twitter）の執行会長兼CTOを務めた。南アフリカ共和国、カナダ、アメリカ合衆国の国籍を持つ。','ja','イーロン・マスク');
INSERT OR REPLACE INTO person VALUES ('318503','Mark Cuban','マーク・キューバン','American investor and entrepreneur (born 1958)','マーク・キューバン（Mark Cuban、1958年7月31日 - ）は、アメリカ合衆国の実業家。NBAのダラス・マーベリックスでオーナーを務めていた。','ja','マーク・キューバン');
INSERT OR REPLACE INTO person VALUES ('3219523','Laurent Solly','','president of Facebook Southern Europe, former campaign director of Nicolas Sarkozy','','','');
INSERT OR REPLACE INTO person VALUES ('32751373','Sanjay Ghemawat','','American computer scientist and software engineer','Sanjay Ghemawat (born 1966 in West Lafayette, Indiana) is an American computer scientist and software engineer. He is currently a Senior Fellow at Google in the Systems Infrastructure Group. Ghemawat''s work at Google, much of it in close collaboration with Jeff Dean, has included big data processing model MapReduce, the Google File System, and databases Bigtable and Spanner. Wired has described him as one of the "most important software engineers of the internet age".','en','Sanjay Ghemawat');
INSERT OR REPLACE INTO person VALUES ('3276951','Tadashi Yanai','柳井正','日本の実業家 (1949-)','柳井 正（やない ただし、1949年〈昭和24年〉2月7日 - ）は、日本の実業家、資産家。カジュアル衣料の製造販売「ユニクロ」を中心とした企業グループ持株会社であるファーストリテイリング代表取締役会長兼社長。ユニクロ代表取締役会長｡ジーユー代表取締役社長。公益財団法人柳井正財団理事長。','ja','柳井正');
INSERT OR REPLACE INTO person VALUES ('328929','Sean Parker','ショーン・パーカー','アメリカの実業家','ショーン・パーカー（Sean Parker、1979年12月3日 - ）は、アメリカ合衆国の実業家であり、起業家。ナップスター、Plaxo、Causesを共同設立し、Facebookの初代CEOを務めた。','ja','ショーン・パーカー');
INSERT OR REPLACE INTO person VALUES ('3299582','Paul Buchheit','ポール・ブックハイト','American computer engineer; created Gmail','ポール・ブックハイト（英語：Paul Buchheit、1977年11月7日 - ）は アメリカのコンピュータプログラマ、起業家。 Gmailを考案、開発を主導した人物として知られる。Gmailのサービスの一部としてプロトタイプのGoogle AdSenseの開発も手掛けた。また、Googleの有名な企業モットー「邪悪になるな」（Don''t be evil）を考案した人物でもある。','ja','ポール・ブックハイト');
INSERT OR REPLACE INTO person VALUES ('335047','Bill Joy','ビル・ジョイ','アメリカ合衆国のコンピュータ科学者・技術者','ウィリアム・ネルソン・ジョイ（William Nelson Joy, 1954年11月8日 - ）、通称ビル・ジョイ（Bill Joy）は、アメリカ合衆国のコンピュータ科学者でありコンピュータ技術者。KPCB パートナー。元サン・マイクロシステムズチーフサイエンティスト。BSD開発の初期にまとめ役として働き、テキストエディタ『vi』を開発したことで知られている。 漢字を勉強したことがあり、日本を訪れた際のサインで名前を「美流上位」と書いている。','ja','ビル・ジョイ');
INSERT OR REPLACE INTO person VALUES ('335552','Jack Dorsey','ジャック・ドーシー','アメリカ合衆国のソフトウェアデザイナー、コンピューター科学者、実業家','ジャック・ドーシー（Jack Patrick Dorsey、1976年11月19日 - ）は、アメリカ合衆国の起業家、実業家、ソフトウェア・デザイナー。Twitterの共同創業者、同社の元最高経営責任者。','ja','ジャック・ドーシー');
INSERT OR REPLACE INTO person VALUES ('3503829','Sundar Pichai','サンダー・ピチャイ','インド系アメリカ人の企業経営者、Google LLC および Alphabet Inc. の CEO','スンダー・ピチャイ（タミル語: சுந்தர் பிச்சை、英語: Sundar Pichai、 1972年6月10日 - ）は、インド出身のインド系アメリカ人（英語版）の経営者で、Google 及び Google親会社である Alphabet の最高経営責任者。2015年の就任当初は日本語で「サンダー・ピチャイ」との表記であったが、現在は「スンダー・ピチャイ」と表記されている。','ja','スンダー・ピチャイ');
INSERT OR REPLACE INTO person VALUES ('3571662','Yann LeCun','ヤン・ルカン','フランスの計算機科学者','ヤン・アンドレ・ルカン（Yann André LeCun、1960年7月8日 - ）は、フランス出身の計算機科学者で、主に機械学習、コンピュータビジョン、移動ロボット、計算神経科学の研究を行っている。ニューヨーク大学クーラント数理科学研究所のシルバー教授、Meta（旧Facebook社）のヴァイスプレジデント兼チーフAIサイエンティストである。 畳み込みニューラルネットワーク(CNN)の主要な創始者の一人であり、それを用いた光学文字認識やコンピュータビジョンの研究で知られる。また、レオン・ボトゥー、パトリック・ハフナーらとともに画像圧縮技術DjVuを創始し、ボトゥーとともにプログラミング言語Lushを開発した。 ディープラーニングに関する研究が評価され、ヨシュア・ベンジオ、ジェフリー・ヒントンとともに2018年のチューリング賞を受賞した。この3人は、「AIのゴッドファーザー」「ディープラーニングのゴッドファーザー」と呼ばれている。 姓の本来の綴りは2語の"Le Cun"である。ルカンの先祖はブルターニュ北部ガンガン地方の出身であり、この語はブルトン語の古い形の"Le Cunff"（直訳すると「いい男」）に由来する。','ja','ヤン・ルカン');
INSERT OR REPLACE INTO person VALUES ('36215','Mark Zuckerberg','マーク・ザッカーバーグ','アメリカ合衆国の実業家','マーク・エリオット・ザッカーバーグ（Mark Elliot Zuckerberg、1984年5月14日 - ）は、アメリカ合衆国のプログラマー、実業家。Meta Platforms, Inc.（旧称: Facebook, Inc.）の共同創業者兼会長兼CEO。 ハーバード大学在籍中にソーシャル・ネットワーキング・サービスサイト「Facebook」を立ち上げた。2010年のTime誌「パーソン・オブ・ザ・イヤー」に選ばれた。','ja','マーク・ザッカーバーグ');
INSERT OR REPLACE INTO person VALUES ('389597','Russell Coutts','ラッセル・クーツ','sailboat designer','Sir Russell Coutts (born 1 March 1962) is a world champion New Zealand yachtsman. He won an Olympic gold medal and skippered three Americas Cup victories in 1995, 2000, and 2003.','en','Russell Coutts');
INSERT OR REPLACE INTO person VALUES ('4088422','Trevor Blackwell','トリヴァー・ブラックウェル','カナダのプログラマ','トレバー・ブラックウェル（英語: Trevor Blackwell、1969年11月4日 - ）は、カナダ系アメリカ人のコンピュータプログラマー、エンジニア、起業家であり、ロボット工学者である。 ブラックウェルは、ヒューマノイドの開発者である。Anybotsの創設者兼元CEOであり、Y Combinatorのパートナーでもある。','ja','トレバー・ブラックウェル');
INSERT OR REPLACE INTO person VALUES ('4149880','Dmitry Grishin','','businessperson','Dmitry Sergeevich Grishin (Russian: Дмитрий Сергеевич Гришин; born 15 October 1978) is a businessman, investor and Internet entrepreneur. He is best known as the co-founder and former chairman and CEO of Mail.ru Group. Grishin also made significant contributions to Russia''s internet presence, Runet, in its early days.','en','Dmitry Grishin');
INSERT OR REPLACE INTO person VALUES ('41812531','Andy Jassy','アンディ・ジャシー','アメリカ合衆国の実業家 (1968-)','アンドリュー・R・ ジャシー（Andrew R. Jassy、1968年1月13日 - ）は、アメリカ合衆国の経営者。AmazonのCEO兼社長。かつてはAmazon Web ServicesのCEOを務めていた。','ja','アンディ・ジャシー');
INSERT OR REPLACE INTO person VALUES ('418622','Akio Toyoda','豊田章男','日本の実業家、レーシングドライバー、フィールドホッケー選手 (1956-)','豊田 章男（とよだ あきお、1956年〈昭和31年〉5月3日 - ）は、日本の実業家、レーシングドライバー、フィールドホッケー選手。愛知県名古屋市出身。 役職はトヨタ自動車代表取締役会長、トヨタ モーター ノース アメリカ取締役会長兼CEO、トヨタ不動産代表取締役会長、トヨタ・モビリティ基金理事長、ルーキーレーシング代表取締役、トヨタ・ガズー・レーシングチームオーナー（WEC）兼会長（WRC）。 学位は法学士（慶應義塾大学・1979年）、経営学修士（バブソン大学・1982年）。栄典は藍綬褒章、レジオンドヌール勲章オフィシエ章、旭日大綬章。 一人の車好きとして「モリゾウ」を名乗り、モータースポーツやマスメディアに登場することでも知られる。また学校訪問の時は「あきちゃん」と名乗ることもある。','ja','豊田章男');
INSERT OR REPLACE INTO person VALUES ('4239903','Melanie Craft','','Fourth wife of American billionaire Larry Ellison','Lawrence Joseph Ellison (born August 17, 1944) is an American businessman. He co-founded the technology company Oracle Corporation, serving as its CEO from 1977 to 2014, and as its CTO and executive chairman since 2014. He remains the single largest shareholder of Oracle and of the mass media and entertainment conglomerate Skydance, which is managed by his son David Ellison.','en','Larry Ellison');
INSERT OR REPLACE INTO person VALUES ('4261025','Jessica Livingston','ジェシカ・リビングストン','American businesswoman and writer','ジェシカ・リビングストン（Jessica Livingston、1971年 - ）は、アメリカの投資家、作家、ポッドキャスターである。彼女は、シードステージベンチャー企業であるYコンビネーターの共同設立者の一人であり、共同設立者であるポール・グレアムの妻である。','ja','ジェシカ・リビングストン');
INSERT OR REPLACE INTO person VALUES ('4407963','Lauren Sánchez','ローレン・サンチェス','American media personality','ローレン・ウェンディ・サンチェス（Lauren Wendy Sánchez、1969年12月19日 - ）は、エミー賞受賞歴もあるアメリカ人ニュースキャスター（アンカー）である。女優やパイロット、実業家としての顔も持つ。『ザ・ビュー』のゲスト司会者の仕事が多く、以前はFOX 11チャンネルの人気番組グッドディLAの共同司会者やエクストラのアンカー、特派員役もこなしていた。ラリー・キング・ライブやジョイ・ベハー・ショー、ショービズ・トゥナイトなどにも定期的に出演している。','ja','ローレン・サンチェス');
INSERT OR REPLACE INTO person VALUES ('45309296','Julia Milner','','','','','');
INSERT OR REPLACE INTO person VALUES ('463877','Melinda Gates','メリンダ・フレンチ・ゲイツ','アメリカの女性実業家、慈善家','メリンダ・フレンチ・ゲイツ（英語: Melinda French Gates, 1964年8月15日 - ）は、アメリカ合衆国の実業家、慈善家で、ビル&メリンダゲイツ財団の元共同会長。ビル・ゲイツの元妻で、旧姓名はメリンダ・アン・ゲイツ（英語: Melinda Ann Gates）、旧姓名はメリンダ・アン・フレンチ（英語: Melinda Ann French）。','ja','メリンダ・ゲイツ');
INSERT OR REPLACE INTO person VALUES ('4678962','Adam Dell','','American businessman','Adam R. Dell (born January 14, 1970) is an American venture capitalist and the brother of Michael Dell, the founder of computer manufacturing company Dell Inc.','en','Adam Dell');
INSERT OR REPLACE INTO person VALUES ('47030267','Oriol Vinyals','オリオール・ヴィニャルズ','machine learning researcher','Oriol Vinyals (born 1983) is a Spanish machine learning researcher. He has developed most of his career at DeepMind. He is a co-founder of Discovery Loop, and was technical lead on Gemini until August 2026, along with Jeff Dean.','en','Oriol Vinyals');
INSERT OR REPLACE INTO person VALUES ('47213','Warren Buffett','ウォーレン・バフェット','アメリカの投資家 (1930-)','ウォーレン・エドワード・バフェット（英語: Warren Edward Buffett、1930年8月30日 - ）は、アメリカ合衆国（米国）の投資家、経営者、資産家、慈善家。ジョージ・ソロス、ジム・ロジャーズとともに世界三大投資家として知られる。 元々は繊維会社だったバークシャー・ハサウェイの経営権を1965年に掌握し、時価総額で世界最大の投資会社に育て上げた。2025年末にCEOをグレッグ・アベルに譲り、翌2026年9月18日付で会長も退いて名誉会長となり、会長は長男のハワード・グレアム・バフェットが引き継いだ。 地元ネブラスカ州オマハを中心とした生活を送っているため、1997年に『ニューヨークタイムス』から「オマハの賢人」（Oracle (Sage) of Omaha）と呼ばれた。大統領自由勲章を受章している。','ja','ウォーレン・バフェット');
INSERT OR REPLACE INTO person VALUES ('4721504','Alexis Ohanian','アレクシス・オハニアン','American businessman','Alexis Kerry Ohanian (born April 24, 1983) is an Armenian-American internet entrepreneur and investor. He is best known as the co-founder and former executive chairman of the social media site Reddit along with Steve Huffman and Aaron Swartz. He also co-founded the early-stage venture capital firm Initialized Capital, helped launch the travel search website Hipmunk and started the social enterprise Breadpig.','en','Alexis Ohanian');
INSERT OR REPLACE INTO person VALUES ('4822287','Auren Hoffman','','American businessman','Auren Raphael Hoffman (born 1974) is an American entrepreneur, angel investor, and author. He is a general partner at Flex Capital, a venture capital tech investment firm. He is the founder and former CEO of SafeGraph, a company that gathers location data from mobile devices and sells anonymized data about human movement at an aggregated spatial level.','en','Auren Hoffman');
INSERT OR REPLACE INTO person VALUES ('4885859','Ben Horowitz','ベン・ホロウィッツ','American businessman','ベンジャミン・アブラハム・ホロウィッツ（1966年6月13日 - ）は、アメリカの事業家、投資家、ブロガー、および作家。テクノロジー起業家であり、マーク・アンドリーセンとともにベンチャーキャピタル会社アンドリーセン・ホロウィッツの共同設立者。彼は以前、ヒューレット・パッカードが2007年に買収したエンタープライズソフトウェア会社オプスウェアの共同設立者、社長兼最高経営責任者を務めていた。スタートアップに関する本である「Hard Things: 答えがない難問と困難に偉大なリーダーはどう立ち向かうのか」の著者。','ja','ベン・ホロウィッツ');
INSERT OR REPLACE INTO person VALUES ('4909249','Bill Gurley','','American businessman','John William Gurley (born May 10, 1966) is an American venture capitalist. Since 1999, he has been a general partner at Benchmark, a Silicon Valley venture capital firm in San Francisco, California. He is best known for an early investment in Uber in 2011.','en','Bill Gurley');
INSERT OR REPLACE INTO person VALUES ('4934','Larry Page','ラリー・ペイジ','アメリカ合衆国の計算機科学者、インターネット起業家','ローレンス・エドワード・“ラリー”・ペイジ（英語: Lawrence Edward "Larry" Page, 1973年3月26日 - ）は、アメリカ合衆国の実業家。Googleの共同創業者、元最高経営責任者（CEO）。Alphabet元CEO。 すでにGoogle・Alphabetの経営からは退いているがAI需要などで株価が上昇し、フォーブス「世界長者番付」2026年3月では世界ランキング2位（資産2570億ドル・約40.6兆円）である。','ja','ラリー・ペイジ');
INSERT OR REPLACE INTO person VALUES ('4961964','Bret Taylor','ブレット・テイラー','American businessman','ブレット・スティーブン・テイラー（Bret Steven Taylor、1980年 - ）は、アメリカのコンピュータプログラマーであり、起業家である。テイラーはGoogle マップを共同開発したチームを率いたこと、Meta（旧Facebook）の最高技術責任者（CTO）、イーロン・マスクによる買収以前のTwitter取締役会長、Salesforceの共同CEO（共同創業者マーク・ベニオフと共に）を務めたことで最もよく知られている。テイラーはまた、FriendFeedの創設者の一人であり、Quipの開発者でもある。2023年からは、OpenAIの会長とShopifyの取締役を務めている。','ja','ブレット・テイラー');
INSERT OR REPLACE INTO person VALUES ('4963341','Brian Chesky','ブライアン・チェスキー','American businessman & Co-founder and CEO of Airbnb','Brian Joseph Chesky (born August 29, 1981) is an American businessman and industrial designer and the co-founder and CEO of Airbnb. Chesky is the 290th richest person in the world according to Forbes, with a net worth of $9.2 billion, largely due to his 10 percent ownership stake in Airbnb.','en','Brian Chesky');
INSERT OR REPLACE INTO person VALUES ('4981374','Neri Oxman','','研究者','Neri Oxman (Hebrew: נרי אוקסמן; born February 6, 1976) is an American-Israeli designer and former professor known for art that combines design, biology, computing, and materials engineering. She coined the phrase "material ecology" to define her work. Oxman was a professor of Media Arts and Sciences at the MIT Media Lab, where she founded and led the Mediated Matter research group.','en','Neri Oxman');
INSERT OR REPLACE INTO person VALUES ('50300377','Brad Smith','ブラッド・スミス','American lawyer and CLO of Microsoft (born 1959)','ブラッド・スミス（英語: Brad Smith、1959年1月17日 - ）は、アメリカ合衆国の弁護士、実業家。正式な氏名はブラッドフォード・リー・スミス（英語: Bradford Lee Smith）。マイクロソフト副会長兼社長、Netflix社外取締役。','ja','ブラッド・スミス (弁護士)');
INSERT OR REPLACE INTO person VALUES ('50358648','Chris Olah','クリス・オラー','AI研究者、「メカニスティック解釈可能性」の開拓者','クリス・オラー（Chris Olah、本名：Christopher Olah、1993年頃生まれ）は、カナダ出身の機械学習研究者であり、AIの安全性に関する研究を専門とする。AIスタートアップ企業Anthropicの共同創業者の一人として知られ、ニューラルネットワークの内部動作を解明する分野である「メカニスティック解釈可能性（mechanistic interpretability）」の開拓者として広く知られる。','ja','クリス・オラー');
INSERT OR REPLACE INTO person VALUES ('5107317','Chris Malachowsky','クリス・マラコウスキー','アメリカ合衆国の実業家 (1959-)','クリス・マラコウスキー（英：Chris Malachowsky、1959年5月2日 - ）は、アメリカ合衆国のコンピュータ・エンジニア。ジェンセン・フアン、カーティス・プリエムと共に、グラフィック・プロセッサ会社のNVIDIAの共同創業者。同社のエンジニアリング及びオペレーション担当の上級副社長を務めている。','ja','クリス・マラコウスキー');
INSERT OR REPLACE INTO person VALUES ('5195858','Curtis Priem','カーティス・プリエム','American electrical engineer and entrepreneur; co-founder of Nvidia','カーティス・プリエム （英：Curtis R. Priem、1958年 または、 1959年 - ）は、アメリカ合衆国のコンピュータ・エンジニア。1993年にジェンセン・フアン、クリス・マラコウスキーと共にグラフィック・チップ会社「NVIDIA」の共同創業者。2003年に同社を退社し、2006年までに保有する株をすべて売却した。 2024年時点では、レンセラー工科大学の理事会副議長を勤めている。','ja','カーティス・プリエム');
INSERT OR REPLACE INTO person VALUES ('5221979','Dara Khosrowshahi','ダラ・コスロシャヒ','Iranian businessman','Dara Khosrowshahi (Persian: دارا خسروشاهی, Persian pronunciation: [dɑː''ɾɑː xosɾo''ʃɑːhiː]; born May 28, 1969) is an Iranian and American business executive who is the chief executive officer of Uber. He was previously CEO of Expedia Group, a company that owns several travel fare aggregators. He is on the board of directors of BET.com and Hotels.com, and was on the board of The New York Times Company.','en','Dara Khosrowshahi');
INSERT OR REPLACE INTO person VALUES ('5284','Bill Gates','ビル・ゲイツ','アメリカの実業家 (1955-)','ビル・ゲイツ（英語: Bill Gates）、本名：ウィリアム・ヘンリー・ゲイツ3世（英語: William Henry Gates III、1955年10月28日 - ）は、アメリカ合衆国の実業家。幼なじみのポール・アレンとともにマイクロソフトを創業した人物として知られる。マイクロソフトでのキャリアにおいて、ゲイツは会長、最高経営責任者（CEO）、社長、最高ソフトウェア設計者を歴任し、同時に2014年まで個人筆頭株主であった。1970年代から1980年代にかけてのマイクロコンピュータ革命の主要な起業家であった。 シアトルで生まれ育つ。1975年、アレンとともにニューメキシコ州アルバカーキにマイクロソフトを設立。世界最大のパソコン用ソフトウェア会社となり、2000年1月にCEOを退任した後も、スティーブ・バルマーに引き継がれるまで会長兼CEOとして同社を率いた。その後、取締役会会長にとどまり、チーフ・ソフトウェア・アーキテクトに就任した。 1990年代後半、ゲイツのビジネス戦術は反競争的であると批判された。この見解は、数々の裁判でも支持されている。','ja','ビル・ゲイツ');
INSERT OR REPLACE INTO person VALUES ('5307199','Drew Houston','','American Internet entrepreneur','Andrew W. Houston (; born March 4, 1983) is an American Internet entrepreneur best known as the co-founder and CEO of Dropbox, an online backup and storage service. According to Forbes, his net worth is about $2 billion. Houston held 24.4% of voting power in Dropbox before the company filed for IPO in February 2018. He has sat on the board of Meta Platforms since February 2020.','en','Drew Houston');
INSERT OR REPLACE INTO person VALUES ('5335240','Ed Oates','','American businessman','Edward A. Oates (born 1946) is an American businessman. He co-founded Software Development Labs in August 1977 with Larry Ellison and Bob Miner. Software Development Labs later became Oracle Corporation.','en','Ed Oates');
INSERT OR REPLACE INTO person VALUES ('53567356','David Stavens','','American computer scientist','David Stavens is an American entrepreneur and scientist. He has made significant contributions to the field of AI, co-founding the team that developed Stanley, the self-driving car that led to Google''s Waymo, as well as Udacity, an online education platform for technology and AI that has educated millions globally. He also co-founded Nines, a company that built AI-enabled, FDA-approved medical devices.','en','David Stavens');
INSERT OR REPLACE INTO person VALUES ('5366748','Hiroshi Mikitani','三木谷浩史','日本の実業家','三木谷 浩史（みきたに ひろし、1965年〈昭和40年〉3月11日 - ）は、日本の実業家、慈善活動家。楽天グループの創業者であり、代表取締役会長兼社長。兵庫県明石市出身。高祖父は山崎藩主本多忠明。明治維新後本多家は華族になったが没落し、祖母は貧しい家に育つも父親の代で再興。裕福な家に育った三木谷氏は後に楽天を創設した。 新経済連盟代表理事、プロ野球・東北楽天ゴールデンイーグルス会長兼球団オーナー、Jリーグ・ヴィッセル神戸会長、日本プロ野球オーナー会議議長、東京フィルハーモニー交響楽団理事長、東京オリンピック・パラリンピック競技大会組織委員会顧問等も務める。','ja','三木谷浩史');
INSERT OR REPLACE INTO person VALUES ('5523871','Garrett Camp','ギャレット・キャンプ','Canadian entrepreneur','Garrett Camp (born October 4, 1978) is a Canadian-French businessman, investor, and software engineer. He helped build the search engine StumbleUpon and is a co-founder of Uber. He lives in Los Angeles.','en','Garrett Camp');
INSERT OR REPLACE INTO person VALUES ('55615876','Kevin Scott','','Chief Technology Officer at Microsoft','Kevin Scott (born 1972) is chief technology officer at Microsoft. He was previously Senior Vice President of Engineering and Operations at LinkedIn from February 2011 to January 2017.','en','Kevin Scott (computer scientist)');
INSERT OR REPLACE INTO person VALUES ('56037405','Andrej Karpathy','アンドレイ・カルパシー','スロヴァキア系カナダ人のAI研究者 (1983-)','アンドレイ・カーパシー（Andrej Karpathy、1986年10月23日 - ）は、スロバキア系カナダ人の計算機科学者であり、テスラにおいて人工知能およびオートパイロットビジョンのディレクターを務めた人物である。彼はOpenAIの共同設立者であり、以前は同社でディープラーニングおよびコンピュータビジョンを専門としていた。2026年にAnthropicに入社し、事前学習チームに参加した。','ja','アンドレイ・カーパシー');
INSERT OR REPLACE INTO person VALUES ('56101409','Guillaume Lample','','研究者','','','');
INSERT OR REPLACE INTO person VALUES ('561960','Evan Williams','エヴァン・ウィリアムズ','アメリカ合衆国の起業家','エヴァン・クラーク・ウィリアムズ（Evan Clark Williams、1972年3月31日 - ）はアメリカ合衆国の起業家。Blogger、Twitter、Mediumなどを創業したシリアルアントレプレナーとして知られる。','ja','エヴァン・ウィリアムズ');
INSERT OR REPLACE INTO person VALUES ('56222319','Doris Buffett','','American philanthropist','Doris Eleanor Buffett (February 12, 1928 – August 4, 2020) was an American philanthropist also known as the ''retail'' philanthropist and the founder of The Sunshine Lady Foundation, The Learning By Giving Foundation, and The Letters Foundation which she co-founded alongside her younger brother, billionaire Warren Buffett. She was the daughter of Leila (Stahl) and U.S. politician and stockbroker Howard Homan Buffett.','en','Doris Buffett');
INSERT OR REPLACE INTO person VALUES ('58492861','Karén Simonyan','','artificial intelligence researcher','','','');
INSERT OR REPLACE INTO person VALUES ('6173703','Jeff Dean','ジェフ・ディーン','American computer scientist','ジェフリー・アドゲート・ディーン（Jeffrey Adgate "Jeff" Dean 、1968年7月23日 - ）は、アメリカ合衆国の計算機科学者およびソフトウェアエンジニアである。1999年に入社したGoogleでの業績で有名である。2018年から2023年にはGoogle AIを率い、2023年から2026年にはGoogleの主席研究員（chief scientist）を務めた。2026年、27年務めたGoogleを退社し、AI研究スタートアップDiscovery Loopを共同設立した。','ja','ジェフ・ディーン');
INSERT OR REPLACE INTO person VALUES ('6196866','Jim McKelvey','ジム・マッケルヴィ','American computer scientist and businessman','James "Jim" Morgan McKelvey Jr. (born 1965 or 1966) is a New York City-based, American, billionaire, and businessman, who co-founded Block, Inc.(formerly Square). He is a Board Director at Emerson Electric. McKelvey was appointed as an independent director of the Federal Reserve Bank of St. Louis in January 2017. As of September 2026, his net worth was estimated at US$1.8 billion.','en','Jim McKelvey');
INSERT OR REPLACE INTO person VALUES ('62098183','Martin Lorentzon','','Swedish entrepreneur','Sven Hans Martin Lorentzon (pronounced [ˈmǎʈːɪn ˈlôːrɛnˌsɔn]; born 1 April 1969) is a Swedish entrepreneur and co-founder of Tradedoubler and Spotify. From 2013 to 2018 he was on the board of Telia Company. Since April 2019, he has been an expert on Sweden''s immigrants'' integration issues for the Moderate Party commission New Swedish Model.','en','Martin Lorentzon');
INSERT OR REPLACE INTO person VALUES ('6210988','Joe Lonsdale','','American entrepreneur and venture capitalist','Joseph Lonsdale (born 1982 or 1983) is an American entrepreneur and venture capitalist. He co-founded Palantir, Addepar, and OpenGov, and co-founded and works as the managing partner at the technology investment firm 8VC. Lonsdale began his career as an intern at PayPal, then worked as an early executive at Clarium Capital, a hedge fund run by Lonsdale''s mentor, Peter Thiel. In 2004, he, Thiel, and three others co-founded Palantir. Lonsdale left Palantir in 2009.','en','Joe Lonsdale');
INSERT OR REPLACE INTO person VALUES ('62849','Miguel de Icaza','ミゲル・デ・イカザ','メキシコのプログラマ、ソフトウェア開発者','ミゲル・デ・イカザ（Miguel de Icaza, 1972年 - ）は、メキシコのプログラマ、自由ソフトウェア開発者。GNOMEとMonoの開発で著名。 メキシコシティ出身。父は物理学者、母は生物学者という科学者の家庭で育った。メキシコ国立自治大学に進学するが学位は取得しなかった。1992年頃から自由ソフトウェアを製作し始める。','ja','ミゲル・デ・イカザ');
INSERT OR REPLACE INTO person VALUES ('62882','Marc Andreessen','マーク・アンドリーセン','アメリカ合衆国のソフトウェア開発者、投資家','マーク・ローウェル・アンドリーセン（Marc Lowell Andreessen, 1971年7月9日 - ）は、アメリカ合衆国のソフトウェア開発者、投資家。ウェブブラウザのNCSA MosaicやNetscape Navigatorを開発した。世界的に有名なベンチャーキャピタル会社のアンドリーセン・ホロウィッツの共同創業者。','ja','マーク・アンドリーセン');
INSERT OR REPLACE INTO person VALUES ('62901','Sebastian Thrun','セバスチアン・スラン','German-American entrepreneur (born 1967)','セバスチアン・バークハード・スラン（Sebastian Burkhard Thrun; 1967年5月14日 - ）は、ドイツ出身の教育者、プログラマー、ロボット開発者、そしてコンピュータ科学者である。グーグルの副社長・フェローであり、スタンフォード大学のコンピュータ科学で非常勤研究教授を務めていた。Stanford Artificial Intelligence Laboratory (SAIL)の所長を務めていたが、2012年David StavensとMike Sokolskyともにユーダシティを創立し、科学、技術、工学、数学などの分野の授業を無償で提供することに精力を注いでいる。また、グーグル・グラスを開発したGoogle Xの社長も務める。','ja','セバスチアン・スラン');
INSERT OR REPLACE INTO person VALUES ('6318376','Justine Musk','ジャスティン・マスク','Canadian author (born 1972)','Jennifer Justine Musk (née Wilson; born September 2, 1972) is a Canadian author. She is the first ex-wife of Elon Musk and the mother of Vivian Wilson.','en','Justine Musk');
INSERT OR REPLACE INTO person VALUES ('6387836','Ken Howery','','American venture capitalist and US ambassador','Kenneth Alan Howery (; born November 4, 1975) is an American entrepreneur and diplomat who is currently serving as the 27th United States Ambassador to Denmark. He is a co-founder of PayPal and Founders Fund. He served as the U.S. ambassador to Sweden from 2019 to 2021 under President Donald Trump. On December 22, 2024, President-elect Trump announced his intention to nominate Howery as the next U.S. ambassador to Denmark.','en','Ken Howery');
INSERT OR REPLACE INTO person VALUES ('6409751','Kimbal Musk','キンバル・マスク','South African-Canadian-American entrepreneur and restaurateur (born 1972)','Kimbal James Musk (born 20 September 1972) is a South African-born venture capitalist and restaurateur. He co-owns The Kitchen Restaurant Group, with restaurants in Colorado, Chicago, and Austin. He is the co-founder and chairman of Big Green, a 501(c)(3) nonprofit that has built hundreds of outdoor classrooms called Learning Gardens in schoolyards across the United States.','en','Kimbal Musk');
INSERT OR REPLACE INTO person VALUES ('64783806','Kenichiro Yoshida','吉田憲一郎','日本の実業家 (1959-)','吉田 憲一郎（よしだ けんいちろう、1959年〈昭和34年〉10月20日 - ）は、日本の実業家。ソニーグループ株式会社取締役代表執行役会長、ソニー株式会社取締役会長、ソニーセミコンダクタソリューションズ株式会社取締役会長、日本経済団体連合会（経団連）副会長。熊本県出身。','ja','吉田憲一郎');
INSERT OR REPLACE INTO person VALUES ('64853019','Fidji Simo','','French-American businessperson and CEO','Fidji Simo (born 5 October 1985) is a French-American businesswoman and the CEO of AGI Deployment at OpenAI. Prior to OpenAI, she spent a decade at Facebook where she was one of the top executives as the head of Facebook, and was CEO of Instacart from 2021 to 2025. She co-founded ChronicleBio, a technology-enabled biomedical research company focused on research into neuroimmune disorders, and is president of the nonprofit Complex Disorders Alliance (CODA).','en','Fidji Simo');
INSERT OR REPLACE INTO person VALUES ('65344','Andy Bechtolsheim','アンディ・ベクトルシャイム','ドイツ出身の電気工学者、起業家、投資家','アンディ・ベクトルシャイム（Andy Bechtolsheim、1955年9月30日 - ）は、ドイツ出身の電気工学者、起業家、投資家である。1982年にサン・マイクロシステムズを共同設立し、同社の主任ハードウェア設計者を務めた。現在は新興企業アリスタネットワークスの会長に就いている。Googleの初期投資者としても知られ、まだ法人化もされていない段階で出資を行った。2025年時点で「ブルームバーグ・ビリオネア指数」および『フォーブス』によると、推定純資産は289億米ドルで、世界長者番付第68位に位置している。 本名アンドレアス・フォン・ベヒトルスハイム (Andreas von Bechtolsheim)、正式名アンドレアス・マリア・マクシミリアン・フライヘア・フォン・マウヘンハイム・ゲナント・ベヒトルスハイム (Andreas Maria Maximilian Freiherr von Mauchenheim genannt Bechtolsheim)。姓は英語読みでベクトルシャイムとなる。','ja','アンディ・ベクトルシャイム');
INSERT OR REPLACE INTO person VALUES ('6780338','Mary Meeker','メアリー・ミーカー','American venture capitalist and securities analyst','メアリー・G・ミーカー（英: Mary G. Meeker、1959年9月 - ）は、アメリカ合衆国、ウォールストリートの元証券アナリストで現在はベンチャーキャピタリスト。 モバイル系を含むインターネット分野における第一人者であり、2014年にはフォーブス誌の「世界で最も影響力のある女性」で77位にランクインした。','ja','メアリー・ミーカー');
INSERT OR REPLACE INTO person VALUES ('6986957','Neeru Khosla','','Wikimedia Foundation board member','Neeru Khosla (born 1955/1956) is an Indian American businesswoman. Khosla is the co-founder of the non-profit CK12 Foundation and the controlling owner of the Seattle Seahawks of the National Football League (NFL). She, along with her husband Vinod Khosla, acquired the Seahawks in 2026 for over $9 billion.','en','Neeru Khosla');
INSERT OR REPLACE INTO person VALUES ('705525','Peter Thiel','ピーター・ティール','ドイツ系アメリカ人の起業家、投資家 (1967-)','ピーター・アンドレアス・ティール（英：Peter Andreas Thiel、1967年10月11日 - ）は、アメリカ合衆国の起業家、投資家。PayPal、OpenAI、Palantir共同創業者。ドナルド・トランプ元政策顧問。保守系動画サイトRumble支援者。ビルダーバーグ会議運営委員メンバー。Palantir Technologies会長。自由至上主義哲学者。Dialog(組織)共同創設者。 「ペイパルマフィア」の中では「ドン」と呼ばれ、Paypal時代からの友人であるイーロン・マスクとは過去関係が深かった。 「影の米大統領」とも呼ばれることがある。 Facebook（現・Meta）の最初期投資家でもあるが、2022年5月に取締役を辞任した後、CEOのマーク・ザッカーバーグを敵対者リストに加えた政治家候補を支援している。','ja','ピーター・ティール');
INSERT OR REPLACE INTO person VALUES ('7146257','Patrick Collison','パトリック・コリソン','Irish entrepreneur','パトリック・コリソン（Patrick Collison、1988年9月9日生まれ）は、アイルランドの起業家であり、決済システムを提供する ストライプ社の共同創業者にして最高経営責任者。','ja','パトリック・コリソン');
INSERT OR REPLACE INTO person VALUES ('717038','Masayoshi Son','孫正義','日本の実業家 (1957-)','孫 正義（そん まさよし、韓国名：손정의ソン・ジョンウィ、1957年〈昭和32年〉8月11日- ）は、佐賀県鳥栖市出身の実業家、資本家、投資家。本貫は一直孫氏。 ソフトバンクグループ株式会社代表取締役会長兼社長、ソフトバンクグループジャパン株式会社代表取締役、ソフトバンク株式会社創業者兼取締役、福岡ソフトバンクホークス株式会社取締役オーナー、ARMホールディングス取締役会長、公益財団法人自然エネルギー財団会長。','ja','孫正義');
INSERT OR REPLACE INTO person VALUES ('719413','David Heinemeier Hansson','デイヴィッド・ハイネマイヤー・ハンソン','デンマーク出身のプログラマ、ソフトウェア技術者、経営者、著作家、カーレーサー','デイヴィッド・ハイネマイヤー・ハンソン（David Heinemeier Hansson、1979年10月15日 - ）は、デンマーク出身のプログラマ、ソフトウェア技術者、経営者、著作家、カーレーサー。Webアプリケーションフレームワーク「Ruby on Rails」の作者。Basecampの創設者、最高技術責任者（CTO）。通称として「DHH」と表記されることが多い。','ja','デイヴィッド・ハイネマイヤー・ハンソン');
INSERT OR REPLACE INTO person VALUES ('7306657','Reed Hastings','リード・ヘイスティングス','American entrepreneur and education philanthropist','Wilmot Reed Hastings Jr. (born October 8, 1960) is an American billionaire businessman. He is the co-founder of Netflix, which provides the eponymous streaming service. Hastings serves on a number of boards and works with various non-profit organizations. A former president of the California State Board of Education, Hastings is also an advocate for charter schools. As of May 2025, Forbes estimated Hastings''s net worth at US$6.6 billion.','en','Reed Hastings');
INSERT OR REPLACE INTO person VALUES ('738005','Vinod Khosla','ビノッド・コースラ','Indian-American businessman','ビノッド・コースラ（ヒンディー語: विनोद खोसला, 英語: Vinod Khosla, 1955年1月28日 - ）は、インド・プネー生まれのベンチャーキャピタリスト。米サン・マイクロシステムズ社の共同設立者の一人である。','ja','ビノッド・コースラ');
INSERT OR REPLACE INTO person VALUES ('7407093','Sam Altman','サム・アルトマン','アメリカの起業家、投資家、プログラマー','サミュエル・H・アルトマン（Samuel Harris Altman〈 AWLT-mən〉、1985年4月22日 - ）は、アメリカ合衆国の起業家兼投資家でプログラマー。OpenAI社の最高経営責任者でYコンビネータの元代表。Tools For Humanity及びワールドコイン財団共同創業者、チェアマン。核融合クリーンエネルギースタートアップのオクロ及び、ヘリオン・エナジーの会長でもある。なお、苗字のカナ書きについては「オルトマン」のほうが原音に近い。','ja','サム・アルトマン');
INSERT OR REPLACE INTO person VALUES ('7426870','Satya Nadella','サティア・ナデラ','マイクロソフト社のCEO','サティア・ナデラ（英語: Satya Nadella、1967年8月19日 - ）は、インド出身のアメリカの経営者。マイクロソフトCEO兼会長。 マイクロソフト・クラウド・エンタープライズ部門エグゼクティブ・バイスプレジデント、Bing・Xbox・Microsoft Office各最高責任者、清華大学経済管理学院顧問委員。 名のサティア（Satya）は、サンスクリット語（梵語）で「普遍」「絶対的な真理」「実在」などの意。','ja','サティア・ナデラ');
INSERT OR REPLACE INTO person VALUES ('7647630','Susan Buffett','スーザン・バフェット','アメリカ合衆国の活動家','Susan Thompson Buffett (June 15, 1932 – July 29, 2004) was an American activist for the causes of civil rights, abortion rights and birth control, and the first wife of investor Warren Buffett. She was a director of Berkshire Hathaway, owning 2.2 percent of the company worth about $3 billion at the time of her death, making her the 153rd richest person in the world.','en','Susan Buffett');
INSERT OR REPLACE INTO person VALUES ('7803680','Tim Howes','','American computer scientist','Tim Howes (born September 21, 1963) is a software engineer, entrepreneur and author. He is the co-creator of the Lightweight Directory Access Protocol (LDAP), the Internet standard for accessing directory servers. He co-founded enterprise software company Opsware, web browser company Rockmelt, and children''s education company, Know Yourself. He has co-authored two books, several Internet RFCs, and holds several patents.','en','Tim Howes');
INSERT OR REPLACE INTO person VALUES ('7820162','Tomoko Namba','南場智子','日本の女性実業家 (1962-)','南場 智子（なんば ともこ、1962年〈昭和37年〉4月21日 - ）は、日本の実業家、経営者。株式会社ディー・エヌ・エー創業者、代表取締役社長兼会長。NPB・横浜DeNAベイスターズオーナー。 女性初の日本プロ野球オーナー会議議長。','ja','南場智子');
INSERT OR REPLACE INTO person VALUES ('7827568','Tosca Musk','トスカ・マスク','South African filmmaker (born 1974)','Tosca Jane Musk (born 20 July 1974) is a South African filmmaker. She is an executive producer and director of feature films, television programs, and web content. Her work includes the popular television series The Black Dagger Brotherhood, based on J.R. Ward''s vampire book series, K. Bromberg''s Driven, Rachel van Dyken''s Matchmaker''s Playbook, and her web series, Tiki Bar TV.','en','Tosca Musk');
INSERT OR REPLACE INTO person VALUES ('7836291','Travis Kalanick','トラビス・カラニック','American entrepreneur','Travis Cordell Kalanick (; born August 6, 1976) is an American businessman best known as the co-founder and former chief executive officer (CEO) of Uber. Previously he worked for Scour, a peer-to-peer file sharing application company, and was the co-founder of Red Swoosh, a peer-to-peer content delivery network that was sold to Akamai Technologies in 2007. He is currently CEO of Atoms, which owns CloudKitchens, operator of ghost kitchens. Kalanick was CEO of Uber from 2010 to 2017.','en','Travis Kalanick');
INSERT OR REPLACE INTO person VALUES ('84323677','Naval Ravikant','','Indian American entrepreneur and investor','Naval Ravikant (born November 5, 1974) is an Indian-born American entrepreneur and investor. He is the co-founder and chairman of AngelList, a platform for startups, investors, and job seekers. He is an angel investor who has made early-stage investments in companies including Uber, Twitter, Postmates, and Yammer. Ravikant is a recipient of the Edmund Hillary Fellowship. He also co-hosts a podcast with Brett Hall.','en','Naval Ravikant');
INSERT OR REPLACE INTO person VALUES ('879247','Biz Stone','ビズ・ストーン','アメリカの起業家','クリストファー・アイザック・"ビズ"・ストーン（Christopher Isaac "Biz" Stone、1974年3月10日 - ）はアメリカの起業家、投資家。Twitter、Medium、Jelly、Obvious Venturesなどの創業者として知られる。現在はPinterestとObvious Venturesのアドバイザーを務めている。','ja','ビズ・ストーン');
INSERT OR REPLACE INTO person VALUES ('900000001','Fumiaki Koizumi','小泉文明','メルカリ取締役会長・鹿島アントラーズFC代表取締役社長','メルカリの取締役会長。株式会社鹿島アントラーズ・エフ・シーの代表取締役社長も務める。以前はミクシィの取締役執行役員CFOで、創業間もない時期に、Freakout、アカツキ、ラクスル、BASEなどの社外役員も務めた(本人のXのプロフィールによる)。','x','Koizumi');
INSERT OR REPLACE INTO person VALUES ('900000002','Takao Ozawa','小澤隆生（おざーん）','ヤフー元社長・Boost Capital運営','ヤフーの元社長。VCとPEのハイブリッドファンド「Boost Capital」を運営し、JFA(日本サッカー協会)の理事も務める。1999年にビズシークを創業して2001年に楽天に売却。2011年設立のクロコスをヤフーに売却して入社し、2022年4月から2023年9月まで、ヤフーの代表取締役社長を務めた(本人のXのプロフィールと、日本M&Aセンターの紹介による)。','x','ozarnozarn');
INSERT OR REPLACE INTO person VALUES ('901670','Daniel Ek','ダニエル・エク','Swedish businessman (born 1983)','Daniel Georg Ek (Swedish pronunciation: [ˈdɑ̂ːnɪɛl ˈjěːɔrj ěːk]; born 21 February 1983) is a Swedish businessman and technologist. He is the founder and executive chairman of Spotify. As of August 2026, his net worth was estimated at $12.5 billion by Forbes.','en','Daniel Ek');
INSERT OR REPLACE INTO person VALUES ('92466067','Kristianne Gates','','sister of Bill Gates','','','');
INSERT OR REPLACE INTO person VALUES ('92466304','Libby Gates MacPhee','','sister of Bill Gates','','','');
INSERT OR REPLACE INTO person VALUES ('92647','Robert Tappan Morris','ロバート・T・モリス','アメリカ合衆国の計算機科学者、実業家','ロバート・タッパン・モリス（Robert Tappan Morris、1965年11月8日 - ）は、アメリカ合衆国の計算機科学者であり、実業家である。彼は、1988年にインターネット初のワームであるモリスワームを製作したことで広く知られている。 モリスはワームを公開したことで起訴され、1986年に制定されたばかりのコンピュータ詐欺と濫用に関する法律 (CFAA)に基づいて有罪判決を受けた最初の人物となった。彼はその後、最初のウェブアプリケーションの1つであるオンラインストアViawebを共同設立し、ポール・グレアムと共にベンチャーキャピタルの資金調達会社Yコンビネータを設立した。 その後、マサチューセッツ工科大学(MIT)の電気工学・計算機科学科の教員となり、2006年にテニュアを授与された。2019年には全米技術アカデミー会員に選出された。','ja','ロバート・T・モリス');
INSERT OR REPLACE INTO person VALUES ('92650','Paul Graham','ポール・グレアム','米国のLispプログラマーでエッセイスト','ポール・グレアム(Paul Graham、1964年 - )は、米国のLispプログラマーでエッセイスト。『ANSI Common Lisp』や『ハッカーと画家』の著者としても知られている。','ja','ポール・グレアム');
INSERT OR REPLACE INTO person VALUES ('92747','Eric Schmidt','エリック・シュミット','アメリカの技術者、経営者 (1955 - )','エリック・エマーソン・シュミット（Eric Emerson Schmidt, 1955年4月27日 - ）はアメリカ合衆国の技術者、経営者で、Googleの元CEO。Alphabetの元取締役会長。現在は技術顧問。カーネギーメロン大学、プリンストン大学の理事も務めている。字句解析器生成プログラム lex の共同開発者でもある。ドイツ系アメリカ人。 人工知能に関する国家安全保障委員会(NSCAI)委員長、MITインテリジェンスクエスト技術顧問、ビルダーバーグ会議運営委員会メンバー、Rebellion Defense取締役。','ja','エリック・シュミット');
INSERT OR REPLACE INTO person VALUES ('92759','Larry Ellison','ラリー・エリソン','アメリカの実業家 (1944-)','ローレンス・ジョセフ・エリソン（Lawrence Joseph Ellison、1944年8月17日 - ）は、データベースソフトをはじめとする大手ビジネスソフトウェア企業オラクル・コーポレーションの共同設立者であり、元CEO、会長、CTOである。4度の離婚歴を含む私生活や、幾多の訴訟や買収、ビル・ゲイツとの関係など、様々な話題に事欠かない。また、自宅を和風建築にするほどの親日家としても知られている。近年では、中堅中小規模向けSaaS型ビジネスアプリケーション企業のNetSuite社設立メンバーの一人としても知られる。2019年現在の総資産は691億ドルで、2018年の545億ドルから増加し、世界で6番目の富豪である。フィランソロピー活動でも有名である。','ja','ラリー・エリソン');
INSERT OR REPLACE INTO person VALUES ('92764','Sergey Brin','セルゲイ・ブリン','アメリカの実業家、資産家 (1973 - )','セルゲイ・ミハイロヴィッチ・ブリン（英語: Sergey Mikhailovich Brin、1973年8月21日 - ）は、アメリカ合衆国のコンピュータ科学者、実業家。Googleの共同創業者。サーゲイ・ブリンとも表記される。 すでにGoogle・Alphabetの経営からは退いているがAI需要などで株価が上昇し、フォーブス「世界長者番付」2026年3月では世界ランキング3位（資産2370億ドル・約37.4兆円）に位置している。','ja','セルゲイ・ブリン');
INSERT OR REPLACE INTO person VALUES ('92955','Nat Friedman','ナット・フリードマン','アメリカ合衆国のプログラマ','ナサニエル・ドゥーリフ・フリードマン（英語: Nathaniel Dourif Friedman, 1977年8月6日 - ）は、1999年にミゲル・デ・イカザとともにXimianを設立したプログラマ。通称はナット(Nat)。同社は2003年にノベルに買収された。','ja','ナット・フリードマン');
INSERT OR REPLACE INTO person VALUES ('93014','Max Levchin','マックス・レヴチン','American businessman','マックス・ラファエル・レヴチン（Max Rafael Levchin、ウクライナ語: Максиміліан Левчин マクシミリアン・レヴチン、1975年7月11日 - ）はウクライナ生まれの計算機科学者、起業家。PayPalの共同設立者で元CTO。','ja','マックス・レヴチン');
INSERT OR REPLACE INTO person VALUES ('93951145','Harriet Heyman','','novelist and journalist','','','');
INSERT OR REPLACE INTO person VALUES ('94309621','Joseph Hill','','American programmer','','','');
INSERT OR REPLACE INTO person VALUES ('96713601','Junichi Miyakawa','宮川潤一','日本の実業家','宮川 潤一（みやかわ じゅんいち、1965年12月1日 - ）は、日本の実業家。MONET Technologies代表取締役社長兼最高経営責任者、ソフトバンク代表取締役社長執行役員兼CEO、電気通信事業者協会会長。スプリント最高執行責任者なども歴任。孫正義の後継者の1人として知られている。愛知県犬山市出身、花園大学文学部仏教学科仏教学卒業。','ja','宮川潤一');
